DO $ingest$
DECLARE p jsonb := $payload${"ley":{"id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","titulo":"Norma Oficial Mexicana de Emergencia NOM-EM-008-ASEA-2026, Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque","siglas":"NOM-EM-008-ASEA-2026","fecha_publicacion":"2026-10-02","fecha_ultima_reforma":null,"vigente":null,"temas_clave":["Seguridad industrial y operativa","Transporte de gas licuado de petróleo","Auto-tanques y semirremolques","Integridad mecánica y mantenimiento","Capacitación de operadores","Evaluación de la conformidad","Protección ambiental y manejo de residuos","Revisión visual diaria"],"url_original":"https://sidof.segob.gob.mx/notas/docFuente/5800169","tipo":"nom"},"articulos":[{"id":"ed7d0e6e-d721-5ffd-b4b3-38c7a97e99f2","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":0,"identificador":"Nota editorial · instrumento regulatorio","contenido":"<h3>Nota editorial · instrumento regulatorio</h3><p>La NOM-EM-008-ASEA-2026 fue publicada en el Diario Oficial de la Federación el 2 de octubre de 2026. Su transitorio Primero dispone que entra en vigor el 6 de octubre de 2026 y tendrá vigencia de seis meses. El transitorio Segundo reconoce los dictámenes de cumplimiento emitidos previamente conforme a la NOM-EM-006-ASEA-2025 hasta el término de su vigencia. Este registro conserva el texto de la nueva norma por separado; no consolida ni reemplaza el instrumento anterior.</p><p>Fuente oficial: <a href=\"https://sidof.segob.gob.mx/notas/docFuente/5800169\">https://sidof.segob.gob.mx/notas/docFuente/5800169</a>. Edición matutina del DOF: <a href=\"https://sidof.segob.gob.mx/notas/getNewsletter/02-10-2026/Matutina/329985\">https://sidof.segob.gob.mx/notas/getNewsletter/02-10-2026/Matutina/329985</a>. Consulta cotejada el 4 de octubre de 2026.</p>","tipo_articulo":"nota","titulo_nombre":"Información editorial","capitulo_nombre":null,"seccion_nombre":null},{"id":"dc7b7520-e0a7-5838-a74f-7e2e03520bbd","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":1,"identificador":"Preámbulo de la norma","contenido":"<div>NORMA Oficial Mexicana de Emergencia NOM-EM-008-ASEA-2026, Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque.</div>\n<div>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Medio Ambiente.- Secretaría de Medio Ambiente y Recursos Naturales.- ASEA.- Agencia de Seguridad, Energía y Ambiente.</div>\n<div>ANDREA GONZÁLEZ HERNÁNDEZ, Directora Ejecutiva de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos y Presidenta del Comité Consultivo Nacional de Normalización de Seguridad Industrial y Operativa y Protección al Medio Ambiente del Sector Hidrocarburos, con fundamento en el artículo Décimo Noveno Transitorio, segundo párrafo, del Decreto por el que se reforman y adicionan diversas disposiciones de la Constitución Política de los Estados Unidos Mexicanos, en Materia de Energía, publicado en el Diario Oficial de la Federación el 20 de diciembre de 2013; 1o., 2o., fracción I, 17 y 26 fracción VIII de la Ley Orgánica de la Administración Pública Federal; 1o., 2o., 3o., fracción XI, inciso d), 4o., 5o., fracciones III, IV, VI y XXX, 6o., fracción I, inciso a), 27 y 31, fracciones II, IV y VIII, de la Ley de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos; 1, 127 y 164 de la Ley del Sector Hidrocarburos; 1o., 3o., fracción IX, 10, fracciones VIII y XV, 12 párrafo primero y segundo, 24, 30, 31, y 34 de la Ley de Infraestructura de la Calidad; 1o. y 4o. de la Ley Federal de Procedimiento Administrativo; 1 y 3, párrafos primero y segundo, fracciones I, VIII XX y XLVII del Reglamento Interior de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos; 1o., 2o., fracción I, 3o., apartado B, fracción IV, 9 fracciones XXIII y XXXVII, 47 primer párrafo, 48 párrafos primero y tercero y 49 fracción IX del Reglamento Interior de la Secretaría de Medio Ambiente y Recursos Naturales; y</div>\n<div>CONSIDERANDO</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"13f78edf-a2d7-52c2-a575-e180ba97473c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":2,"identificador":"Considerando 1","contenido":"<div>Que el Decreto por el que se reforman y adicionan diversas disposiciones de la Constitución Política de los Estados Unidos Mexicanos, en Materia de Energía, en cuyo artículo Décimo Noveno Transitorio se establece como mandato al Congreso de la Unión realizar adecuaciones al marco jurídico para crear la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos (Agencia), como órgano administrativo desconcentrado de la Secretaría del ramo en materia de medio ambiente, con autonomía técnica y de gestión; con atribuciones para regular y supervisar, en materia de Seguridad Industrial, Seguridad Operativa y protección al medio ambiente, las instalaciones y actividades del Sector Hidrocarburos, incluyendo las actividades de desmantelamiento y abandono de instalaciones, el control integral de Residuos.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"1ac114be-489c-58b8-a913-207b4633d2c7","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":3,"identificador":"Considerando 2","contenido":"<div>Que la Ley del Sector Hidrocarburos, en su artículo 127 establece que la industria del Sector Hidrocarburos es de exclusiva jurisdicción federal, por lo que, únicamente el Gobierno Federal puede dictar las disposiciones técnicas, reglamentarias y de regulación en la materia, incluyendo aquéllas relacionadas con la emisión de gases de efecto invernadero, el desarrollo sustentable, el equilibrio ecológico y la protección al medio ambiente en el desarrollo de esta industria.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"b8b8e2b9-6eca-5de0-86d1-a1201257ea24","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":4,"identificador":"Considerando 3","contenido":"<div>Que de acuerdo con lo establecido en el artículo 119, fracción XV, de la Ley del Sector Hidrocarburos, las personas Permisionarias deben cumplir con la regulación, lineamientos y disposiciones administrativas que emitan la Secretarías de Energía, de Hacienda y Crédito Público y la Agencia, en el ámbito de sus respectivas competencias.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"eb77ff44-eb38-5f6a-8594-bdb8fedb7b04","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":5,"identificador":"Considerando 4","contenido":"<div>Que de conformidad con lo establecido en el artículo 164, de la Ley del Sector Hidrocarburos, corresponde a la Agencia emitir la regulación y la normatividad aplicable en materia de Seguridad Industrial y Seguridad Operativa, así como de protección al medio ambiente en la industria de Hidrocarburos, a fin de promover, aprovechar y desarrollar de manera sustentable las actividades de la industria y aportar los elementos técnicos para el diseño y la definición de la política pública en materia energética, de protección al medio ambiente y recursos naturales.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"352c0516-34c7-5476-8b7e-e76c822fc289","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":6,"identificador":"Considerando 5","contenido":"<div>Que la Ley de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos, establece que esta tiene por objeto la protección de las personas, el medio ambiente y las instalaciones del Sector Hidrocarburos, por lo que cuenta con atribuciones para regular, supervisar y sancionar en materia de Seguridad Industrial, Seguridad Operativa y protección al medio ambiente las actividades del Sector.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"31fd0348-5e81-56d6-b7a0-9db0d5911c59","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":7,"identificador":"Considerando 6","contenido":"<div>Que el Reglamento Interior de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos, detalla el conjunto de facultades que debe ejercer esta Agencia, entre las que se encuentra expedir las normas oficiales mexicanas en materia de su competencia.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"252b6149-7adb-587a-babc-d4f3e91feb34","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":8,"identificador":"Considerando 7","contenido":"<div>Que en términos de lo dispuesto en el artículo 3o., fracción IX, de la Ley de Infraestructura de la Calidad, prevé que a las Autoridades Normalizadoras les corresponde expedir Normas Oficiales Mexicanas en las materias relacionadas con sus atribuciones, determinar su fecha de entrada en vigor y verificar su cumplimiento.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"3352f12d-ae3c-53c9-9b28-79387092b7c9","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":9,"identificador":"Considerando 8","contenido":"<div>Que de conformidad con lo establecido en el artículo 10, fracciones VIII y XV, de la Ley de Infraestructura de la Calidad, las Normas Oficiales Mexicanas tienen como finalidad atender las causas de los problemas identificados por las Autoridades Normalizadoras que afecten o que pongan en riesgo los objetivos legítimos de interés público, entre otros, la protección de las personas, el medio ambiente y las instalaciones del Sector Hidrocarburos.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"c766b4ca-2094-548f-b0c9-0da1e5dba091","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":10,"identificador":"Considerando 9","contenido":"<div>Que el 3 de octubre de 2025 se publicó en el Diario Oficial de la Federación la NORMA Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025, Transporte de Gas Licuado de Petróleo, la cual tenía como objetivo establecer las especificaciones técnicas y requisitos de Seguridad Industrial, Seguridad Operativa y protección al medio ambiente que deben observar los Regulados que realicen la actividad de Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque, en este último caso con su respectivo Tractocamión (Tractocamión-Semirremolque), y que contaba con una vigencia de seis meses contados a partir de su entrada en vigor.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"8bbecf60-5113-518f-b320-53c079bb5c58","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":11,"identificador":"Considerando 10","contenido":"<div>Que de conformidad con el artículo 31, segundo párrafo, de la Ley de Infraestructura de la Calidad, y 35, segundo párrafo del Reglamento de la Ley Federal sobre Metrología y Normalización, el 01 de abril de 2026 se publicó en el Diario Oficial de la Federación el AVISO por el cual se prorroga por un plazo de seis meses la vigencia de la NORMA Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025, Transporte de Gas Licuado de Petróleo, publicada en el Diario Oficial de la Federación el 3 de octubre de 2025.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"8469a2a1-6a37-5819-8f93-25f529f232fb","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":12,"identificador":"Considerando 11","contenido":"<div>Que de conformidad con lo establecido en el artículo 5, fracción XLVIII, de la Ley del Sector Hidrocarburos la actividad de Transporte consiste en recibir, entregar y, en su caso, conducir Hidrocarburos, Petrolíferos y Petroquímicos, de un lugar a otro por medio de ductos u otros medios, que no conlleva la compraventa o Comercialización de dichos productos por parte de quien la realiza, actividad que, para el caso de Gas Licuado de Petróleo, conforme lo indicado en el artículo 123 del Reglamento de la Ley del Sector Hidrocarburos, podrá llevarse a cabo mediante Auto-tanques, Semirremolques, Carro-tanques o Buque-tanques, así como en los demás medios que establezcan la Secretaría de Energía y la Comisión Nacional de Energía, en el ámbito de su competencia.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"6de6e0c0-88d7-5e9f-a295-b414d21771ca","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":13,"identificador":"Considerando 12","contenido":"<div>Que el artículo 31, de la Ley de Infraestructura de la Calidad establece que las Normas Oficiales Mexicanas de Emergencia serán elaboradas directamente y emitidas por las Autoridades Normalizadoras, cumpliendo con lo previsto en el artículo 34 de la referida Ley, cuando busquen evitar un daño inminente, o bien atenuar o eliminar un daño existente a algún objetivo legítimo de interés público, señalando que tendrán una vigencia no mayor a seis meses, misma que podrá ser prorrogada en una sola ocasión, hasta por un periodo igual, si así lo considera la autoridad emisora, y se ordenará su publicación en el Diario Oficial de la Federación.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"a11e8447-3ccb-5f6c-847d-7ecd91a645e6","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":14,"identificador":"Considerando 13","contenido":"<div>Que en ese sentido el Transporte de Gas Licuado de Petróleo mediante Semirremolque y Auto-tanque es una actividad de alto riesgo debido a las propiedades y comportamiento inherentes a dicho gas, y al realizar esta actividad se han registrado múltiples accidentes que han dejado daños considerables a la población, incluyendo la pérdida de vidas humanas, lo cual hace necesario establecer las especificaciones técnicas y requisitos para garantizar la Seguridad Industrial, la Seguridad Operativa y la protección del medio ambiente durante el Transporte de Gas Licuado de Petróleo mediante Semirremolque y Auto-tanque.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"07bbcca2-1f66-51cf-af0a-29c74f37632a","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":15,"identificador":"Considerando 14","contenido":"<div>Que de acuerdo con el registro de esta Agencia referente a la ocurrencia de incidentes o accidentes relacionados con el traslado de Gas Licuado de Petróleo por Auto-tanques y Semirremolques, se tiene que estos han sido ocasionados por fallas mecánicas del Tractocamión que arrastra el Semirremolque o fallas en la parte motriz del Auto-tanque, así como por prácticas inadecuadas de conducción, exceso de velocidad, pérdida de control de la unidad, volcaduras, entre otras, generando eventos como fugas en el recipiente o sus componentes, incendios y explosiones, ocasionando graves impactos como lesiones a la población, pérdidas humanas y daños materiales y al medio ambiente.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"d59e15d3-b06a-5f04-a8a9-4a4c3fd19f14","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":16,"identificador":"Considerando 15","contenido":"<div>Que posterior a la publicación de la NORMA Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025, Transporte de Gas Licuado de Petróleo, se inscribió en el Programa Nacional de Infraestructura de la Calidad 2026, publicado en el Diario Oficial de la Federación el 24 de febrero de 2026, el tema Transporte de Gas Licuado de Petróleo por Auto-tanque y Semirremolque, para ser desarrollado como Norma Oficial Mexicana definitiva, de acuerdo con lo establecido en el segundo y tercer párrafo del artículo 29 de la Ley de Infraestructura de la Calidad; para posteriormente ser presentado y aprobado, el 8 de abril de 2026, por el Comité Consultivo Nacional de Normalización de Seguridad Industrial y Operativa y Protección al Medio Ambiente del Sector Hidrocarburos (CONASEA), como Proyecto de Norma Oficial Mexicana PROY-NOM-029-ASEA-2026, Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque, para su consulta pública, cuyo periodo ha concluido, lo anterior conforme a lo establecido en los artículos 35, fracciones II, IV y VI y 38 de la Ley de Infraestructura de la Calidad.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"07b16983-72ea-5616-84fa-e367cd36b73b","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":17,"identificador":"Considerando 16","contenido":"<div>Que para contar con una Norma Oficial Mexicana definitiva que regule el Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque se requiere concluir las etapas de presentación ante el CONASEA de la respuesta a los comentarios recibidos durante la consulta pública y, como consecuencia, la propuesta de ajustes al proyecto de Norma Oficial Mexicana, para su resolución definitiva; ordenar su publicación en el Diario Oficial de la Federación y concluir el periodo mínimo de entrada en vigor de las Normas Oficiales Mexicanas, conforme a lo previsto en los artículos 35, fracciones VIII, IX y X, y 39 de la Ley de Infraestructura de la Calidad.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"707c11bb-cc9a-58ac-bd72-e238d7733f22","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":18,"identificador":"Considerando 17","contenido":"<div>Que atendiendo a las consideraciones anteriores para evitar que se realice la actividad de Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque sin que exista un marco normativo para la prevención, control y mitigación de los riesgos, considerando, entre otras, el mantenimiento preventivo, correctivo, inspecciones y pruebas para conservar la integridad mecánica de las Unidades de Transporte incluyendo el Recipiente No Desmontable, las válvulas, los equipos y accesorios, la parte motriz y cualquier elemento que pueda generar una condición de riesgo, así como los procedimientos de operación, prácticas seguras, capacitación teórico - práctica y desempeño del personal; se requiere emitir un instrumento regulatorio para favorecer el desarrollo de una industria segura y la consecución de los objetivos legítimos de interés público a cargo de esta Agencia.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"a1319c99-ba0b-5432-acff-491ebd0f5d2d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":19,"identificador":"Considerando 18","contenido":"<div>Que, en virtud de lo antes expuesto, se expide la Norma Oficial Mexicana de Emergencia NOM-EM-008-ASEA-2026, Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque.</div>\n<div>Ciudad de México, a los nueve días del mes de septiembre de dos mil veintiséis.- La Directora Ejecutiva de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos y Presidenta del Comité Consultivo Nacional de Normalización de Seguridad Industrial y Operativa y Protección al Medio Ambiente del Sector Hidrocarburos, Andrea González Hernández.- Rúbrica.</div>","tipo_articulo":"preambulo","titulo_nombre":"Preámbulo","capitulo_nombre":null,"seccion_nombre":null},{"id":"ddfa22fa-58e4-5a6c-8d1c-174c324f7bda","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":20,"identificador":"Numeral 1. Objetivo","contenido":"<div>1. Objetivo</div>\n<div>La presente Norma Oficial Mexicana de Emergencia establece las especificaciones técnicas y requisitos de Seguridad Industrial, Seguridad Operativa y protección al medio ambiente que deben cumplir los Regulados que realicen la actividad de Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque, en este último caso con su respectivo Tractocamión (Tractocamión-Semirremolque).</div>","tipo_articulo":"ordinario","titulo_nombre":"Objetivo","capitulo_nombre":null,"seccion_nombre":null},{"id":"0076ea67-a8d0-5e8a-a6bc-78cd61bc0703","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":21,"identificador":"Numeral 2. Campo de aplicación","contenido":"<div>2. Campo de aplicación</div>\n<div>Aplica en todo el territorio nacional y es de observancia general y obligatoria para los Regulados que lleven a cabo las siguientes actividades:</div>\n<div>Lo anterior, para el inicio de operación, durante la operación y mantenimiento y hasta el término de la operación de la Unidad de Transporte.</div>","tipo_articulo":"ordinario","titulo_nombre":"Campo de aplicación","capitulo_nombre":null,"seccion_nombre":null},{"id":"52b03747-f9dc-5b5a-a87c-144872c95b0d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":22,"identificador":"Numeral 3. Objetivos legítimos de interés público","contenido":"<div>3. Objetivos legítimos de interés público</div>\n<div>La presente Norma Oficial Mexicana de Emergencia atiende las causas que pudieran afectar la seguridad e integridad de las personas, el medio ambiente y las Instalaciones del Sector Hidrocarburos derivado de la actividad de Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque, en este último caso con su respectivo Tractocamión (Tractocamión-Semirremolque).</div>","tipo_articulo":"ordinario","titulo_nombre":"Objetivos legítimos de interés público","capitulo_nombre":null,"seccion_nombre":null},{"id":"14fea294-b5c5-50de-9460-857d108d95bd","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":23,"identificador":"Numeral 4. Referencias normativas","contenido":"<div>4. Referencias normativas</div>\n<div>Para la correcta aplicación de la presente Norma Oficial Mexicana de Emergencia deben consultarse los siguientes documentos normativos vigentes o aquellos que los modifiquen o sustituyan:</div>","tipo_articulo":"ordinario","titulo_nombre":"Referencias normativas","capitulo_nombre":null,"seccion_nombre":null},{"id":"fe029da0-5301-51ef-9116-1f263f10af18","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":24,"identificador":"Numeral 5. Términos, definiciones, términos abreviados, símbolos y siglas","contenido":"<div>5. Términos, definiciones, términos abreviados, símbolos y siglas</div>","tipo_articulo":"ordinario","titulo_nombre":"Términos, definiciones, términos abreviados, símbolos y siglas","capitulo_nombre":null,"seccion_nombre":null},{"id":"ccc9d4e4-a98f-5d1b-a07c-a116f1e47eac","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":25,"identificador":"Numeral 5.1","contenido":"<div>5.1. Términos y definiciones</div>\n<div>Para efectos de la interpretación y aplicación de la presente Norma Oficial Mexicana de Emergencia, se sujetará a los términos y definiciones en singular o plural, previstos en la Ley de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos, la Ley del Sector Hidrocarburos, la Ley de Infraestructura de la Calidad, la Ley General del Equilibrio Ecológico y la Protección al Ambiente, el Reglamento de la Ley del Sector Hidrocarburos, el Reglamento Interior de la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos, las Normas Oficiales Mexicanas y las Disposiciones administrativas de carácter general competencia de la Agencia y las definiciones siguientes:</div>","tipo_articulo":"ordinario","titulo_nombre":"Términos, definiciones, términos abreviados, símbolos y siglas","capitulo_nombre":"5 · Términos, definiciones, términos abreviados, símbolos y siglas","seccion_nombre":"5.1"},{"id":"9a1a5a13-d18a-569d-877b-567bfe6580b4","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":26,"identificador":"Numeral 5.2","contenido":"<div>5.2. Términos abreviados, símbolos y siglas</div>\n<div>Para efectos de la aplicación e interpretación de la presente Norma Oficial Mexicana de Emergencia, se emplean los términos abreviados, símbolos y siglas siguientes:</div>\n<table><tbody><tr><td>°C</td><td>Grado Celsius</td></tr><tr><td>cm</td><td>Centímetro</td></tr><tr><td>CONOCER</td><td>Consejo Nacional de Normalización y Certificación de Competencias Laborales</td></tr><tr><td>GLP</td><td>Gas Licuado de Petróleo</td></tr><tr><td>h</td><td>Hora</td></tr><tr><td>K</td><td>Kelvin</td></tr><tr><td>kg</td><td>Kilogramo</td></tr><tr><td>LIC</td><td>Ley de Infraestructura de la Calidad</td></tr><tr><td>m</td><td>Metro</td></tr><tr><td>min</td><td>Minuto</td></tr><tr><td>mm</td><td>Milímetro</td></tr><tr><td>MPa</td><td>Megapascal</td></tr><tr><td>ONU</td><td>Organización de las Naciones Unidas</td></tr><tr><td>PEC</td><td>Procedimiento de Evaluación de la Conformidad</td></tr><tr><td>SICT</td><td>Secretaría de Infraestructura, Comunicaciones y Transportes</td></tr><tr><td>STPS</td><td>Secretaría del Trabajo y Previsión Social</td></tr></tbody></table>","tipo_articulo":"ordinario","titulo_nombre":"Términos, definiciones, términos abreviados, símbolos y siglas","capitulo_nombre":"5 · Términos, definiciones, términos abreviados, símbolos y siglas","seccion_nombre":"5.2"},{"id":"b96bcc2f-c36b-5337-94d2-98f77755ffd2","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":27,"identificador":"Numeral 6. Inicio de operación","contenido":"<div>6. Inicio de operación</div>\n<div>Para el inicio de operación de las actividades de Transporte de GLP por medio de Tractocamión-Semirremolque y Auto-tanque, con Recipiente No Desmontable nuevo o usado, se deben cumplir como mínimo las especificaciones y requisitos siguientes:</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":null,"seccion_nombre":null},{"id":"7a5f2247-b024-5620-b694-7f736a9845e2","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":28,"identificador":"Numeral 6.1","contenido":"<div>6.1. Requisitos generales de la Unidad de Transporte</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6 · Inicio de operación","seccion_nombre":"6.1"},{"id":"f2c0a7c0-e9d7-57d3-bc37-566eb4534b2e","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":29,"identificador":"Numeral 6.1.1","contenido":"<div>6.1.1. El Recipiente No Desmontable debe contar con una placa de datos legible en un lugar visible y accesible, instalado de forma fija y permanente, que contenga, como mínimo, la información siguiente:</div>\n<div>a) Nomenclatura de la NOM-009-SESH-2011 o aquella vigente en su fecha de fabricación o, en su caso, especificación de la SICT;</div>\n<div>b) Nombre del fabricante y fecha de fabricación;</div>\n<div>c) Capacidad nominal en litros de agua;</div>\n<div>d) Presión de diseño;</div>\n<div>e) Diámetro exterior o interior, excepto si fue construido con la NOM-057-SCT2/2003;</div>\n<div>f) Longitud total, excepto si fue construido con la NOM-057-SCT2/2003;</div>\n<div>g) Espesor nominal de las placas de cuerpo y cabezas, y</div>\n<div>h) Número de serie o número único de identificación.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.1"},{"id":"b45788c6-cf6c-56a1-9fa4-b455cbb6f9f2","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":30,"identificador":"Numeral 6.1.2","contenido":"<div>6.1.2. El Semirremolque y el chasis del Auto-tanque deben estar diseñados para soportar la carga del Recipiente No Desmontable al 100 % de su capacidad de GLP, especificación que debe ser amparada en el documento emitido por el fabricante del vehículo.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.2"},{"id":"82818e31-46b3-5ca6-8fcc-f8cd080c66a4","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":31,"identificador":"Numeral 6.1.3","contenido":"<div>6.1.3. El Recipiente No Desmontable debe estar instalado sobre una placa de asiento sujeta al chasis del Auto-tanque o al Semirremolque, para evitar su desplazamiento durante el movimiento. Estas placas de asiento deben tener un espesor mínimo de 6.35 mm, debiendo extenderse de manera uniforme por lo menos cuatro veces su espesor en todas direcciones, soldándose en toda la periferia. Cualquier elemento de sujeción unido al Recipiente No Desmontable debe soldarse o atornillarse a la placa de asiento y, en ningún caso debe soldarse directamente al recipiente, refuerzo o accesorio alguno. El anclaje del Recipiente No Desmontable al chasis debe incluir una base de amortiguamiento.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.3"},{"id":"29950e1c-cd46-5d2b-991a-e60c33efaaee","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":32,"identificador":"Numeral 6.1.4","contenido":"<div>6.1.4. La Unidad de Transporte debe portar las siguientes señales y avisos en el Recipiente No Desmontable mismas que deben ser claras, legibles y visibles en caracteres no menores a 6 cm, de acuerdo con lo siguiente:</div>\n<div>a) Nombre, razón social o marca comercial del Regulado;</div>\n<div>b) Identificación de la Unidad de Transporte, mediante el número de permiso otorgado por la autoridad competente en materia del Sector Hidrocarburos y número económico;</div>\n<div>c) La leyenda &quot;SERVICIO PARA EL TRANSPORTE DE GAS L.P.&quot;;</div>\n<div>d) La leyenda &quot;PELIGRO GAS L.P.&quot;;</div>\n<div>e) Números telefónicos para la atención a emergencias y reportes de fugas de GLP;</div>\n<div>f) Domicilio de la Instalación o central de resguardo donde pernocta la Unidad de Transporte, autorizada por la autoridad competente en materia del Sector Hidrocarburos;</div>\n<div>g) Capacidad de la Unidad de Transporte al 100 % en litros de agua;</div>\n<div>h) Capacidad de la Unidad de Transporte al 90% en litros de agua, y</div>\n<div>i) Cartel de identificación que incluya el símbolo de acuerdo con la clase y número internacional de identificación conforme al Sistema de Identificación para Unidades Destinadas al Transporte de Materiales y Residuos Peligrosos (1075 y clase 2) para GLP de acuerdo con la Figura 1 o 2, y que cumpla como mínimo con lo siguiente:</div>\n<div>1. Colocarse uno a cada costado y en la parte posterior del Recipiente No Desmontable, para configuraciones vehiculares doblemente articuladas, los rótulos se colocarán en ambos Semirremolques. Adicional a lo anterior, se debe colocar este cartel de identificación en la parte frontal del Tractocamión, siempre y cuando no se obstruya la visibilidad del conductor.</div>\n<div>2. Colocarse sobre un fondo de color que ofrezca contraste o estar rodeados de un borde de trazo continuo o discontinuo; y estar situados de tal forma, que no se obstruya o confunda su visibilidad, y</div>\n<div>3. Forma de rombo con dimensiones mínimas de 250 mm x 250 mm por lado y con una línea del mismo color del símbolo trazada a 12.5 mm del borde exterior.</div>\n<div>4. El número ONU de las mercancías peligrosas figurará en cifras negras de una altura mínima de 65 mm.</div>\n<div><img src=\"https://sidofqa.segob.gob.mx/imagenes_diarios/2026/10/02/MAT/semarnat_1_Cimg_1782.png\" alt=\"Figura oficial 1 de la NOM\" loading=\"lazy\"></div>\n<div>Figura 1. Cartel de Identificación para GLP</div>\n<div><img src=\"https://sidofqa.segob.gob.mx/imagenes_diarios/2026/10/02/MAT/semarnat_1_Cimg_662151.png\" alt=\"Figura oficial 2 de la NOM\" loading=\"lazy\"></div>\n<div>Figura 2. Cartel de Identificación alternativo</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.4"},{"id":"0f6ef773-d6d8-5e09-94ad-703037b65a4c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":33,"identificador":"Numeral 6.1.5","contenido":"<div>6.1.5. Cada Unidad de Transporte debe contar con:</div>\n<div>a) Al menos un extintor portátil a bordo, con capacidad de al menos 9 kg de polvo químico seco tipo ABC, con etiqueta de servicio y caducidad vigente;</div>\n<div>b) Cinta estática que toque el piso;</div>\n<div>c) Señales reflejantes para carretera;</div>\n<div>d) Lámpara de mano;</div>\n<div>e) Al menos dos calzas para inmovilización cuya resistencia soporte el peso de la Unidad de Transporte con carga máxima al estar estacionado, y</div>\n<div>f) Medidor o calibrador de presión de neumáticos.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.5"},{"id":"f02b2788-9866-5ded-a99e-2119f2a5e642","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":34,"identificador":"Numeral 6.1.6","contenido":"<div>6.1.6. El Regulado debe contar con los siguientes documentos:</div>\n<div>a) El certificado de fabricación del Recipiente No Desmontable conforme a la NOM-009-SESH-2011, o NOM-057-SCT2/2003, o aquella vigente en su fecha de construcción, así como las recomendaciones emitidas por el fabricante; en caso de que el Regulado no cuente con el certificado de fabricación del Recipiente No Desmontable, debe contar con una copia certificada o, en su caso, con el documento emitido y firmado por el fabricante que avale las especificaciones de diseño y pruebas de fabricación, de conformidad con la Norma Oficial Mexicana vigente en su fecha de fabricación;</div>\n<div>b) Las especificaciones de diseño y fabricación del Recipiente No Desmontable que incluyan, al menos:</div>\n<div>1. Presión de diseño;</div>\n<div>2. Presión(es) de operación;</div>\n<div>3. Presión(es) de trabajo máxima(s) permitida(s);</div>\n<div>4. Espesores de sección cilíndrica y casquetes;</div>\n<div>5. Capacidad volumétrica, y</div>\n<div>6. Número y tipo de dispositivos de relevo de presión, así como presión de calibración.</div>\n<div>c) Hojas de especificaciones técnicas y, en su caso, los certificados de los accesorios y equipos instalados en el Auto-tanque y/o Semirremolque, indicando la fecha de fabricación e instalación de los mismos;</div>\n<div>d) El dictamen aprobatorio vigente de cumplimiento con la NOM-068-SCT-2-2014 del Semirremolque y/o Auto-tanque;</div>\n<div>e) En el caso de Semirremolque, la constancia vigente de cumplimiento con la NOM-035-SCT-2-2022 emitida por el fabricante, y</div>\n<div>f) Cuando la Unidad de Transporte cuente con equipo de carburación de GLP, el dictamen vigente de cumplimiento con la NOM-005-SESH-2010.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.6"},{"id":"208e802c-bb6f-53a6-8c7e-942e454e222e","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":35,"identificador":"Numeral 6.1.7","contenido":"<div>6.1.7. El Auto-tanque y Tractocamión deben contar con un gobernador de velocidad a través de la computadora del motor, o bien en el caso de las Unidades que no cuenten con computadora en el motor, a través de un accionador electromecánico del pedal de frenado; en ambos casos, a efecto de que se restrinja su velocidad hasta un máximo de 80 km/h y contar con el documento que acredite su instalación.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.1 · Requisitos generales de la Unidad de Transporte","seccion_nombre":"6.1.7"},{"id":"2db31a2b-f1be-53cc-8685-600404dc5913","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":36,"identificador":"Numeral 6.2","contenido":"<div>6.2. Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado</div>\n<div>En caso de que el Recipiente No Desmontable del Auto-tanque y del Semirremolque que inicia operaciones como parte del parque vehicular del Regulado no sea nuevo, es decir, que haya sido usado previamente para realizar el Transporte de GLP, además de lo señalado en el numeral 6.1, debe cumplir con lo siguiente:</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6 · Inicio de operación","seccion_nombre":"6.2"},{"id":"cc45a1bc-f145-55d6-8ea6-0e867a2b6a75","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":37,"identificador":"Numeral 6.2.1","contenido":"<div>6.2.1. Contar como mínimo con los siguientes accesorios:</div>\n<div>a) Indicador de nivel de tipo flotador mecánico, magnético o de otro tipo de tecnología, que indique el porcentaje de nivel de GLP contenido en el Recipiente No Desmontable;</div>\n<div>b) Válvulas de máximo llenado, una para el 85 % y otra para el 90 % de su capacidad nominal, como mínimo;</div>\n<div>c) Boquilla provista de un orificio restrictor, destinada a la colocación de un manómetro. Dicha boquilla debe estar conectada a una vena metálica que se extienda hasta la zona por encima del máximo nivel de llenado permisible correspondiente;</div>\n<div>d) Manómetro de tipo Bourdon, para un rango de 0 a 2.06 MPa (0 a 21 kg/cm2) y la medida nominal de su carátula no debe ser menor de 50.8 mm;</div>\n<div>e) Termómetro en un tubo ciego (termopozo) inclinado que permita el llenado con un líquido para la medición de la temperatura. La colocación de este termopozo debe ser a una altura no mayor del centro del diámetro del Recipiente No Desmontable o, en su caso, en el seno del líquido. La carátula del termómetro debe estar legible, sin daños y ser capaz de señalar la lectura en un intervalo mínimo de -20 °C a 50 °C (253 K a 323 K);</div>\n<div>f) Válvulas de exceso de flujo y no retroceso de acuerdo con la configuración del Recipiente No Desmontable, marcadas con la fecha de fabricación legible, nombre del fabricante, capacidad y sentido del flujo de conformidad con la NMX-X-013-SCFI-2011 o aquella vigente en su fecha de fabricación;</div>\n<div>g) Las aberturas que lleven instalada una Válvula de exceso de flujo deben de indicar con caracteres indelebles, las iniciales L o V, si están conectadas a la zona de líquido o de vapor dentro del Recipiente No Desmontable;</div>\n<div>h) Válvulas de llenado y descarga; en caso de que el llenado y/o descarga del Recipiente No Desmontable se realice mediante dispositivos de desconexión seca, éste debe contar con un acoplamiento de llenado y/o descarga de desconexión seca compatible;</div>\n<div>i) Entrada o registro pasa-hombre con diámetro mínimo de 0.38 m;</div>\n<div>j) Matachispas, instalado en el escape, con la documentación que acredite su instalación;</div>\n<div>k) Rompeolas sujetos al tanque, uno como mínimo para Auto-tanques, y dos como mínimo para Semirremolques, y</div>\n<div>l) Válvula de relevo de presión, una como mínimo y debe cumplir con lo siguiente:</div>\n<div>1. Ser de tipo accionada por resorte;</div>\n<div>2. Contar con la información de las especificaciones técnicas del fabricante;</div>\n<div>3. La presión de apertura debe ser igual a la Presión de diseño del Recipiente No Desmontable;</div>\n<div>4. Estar instaladas en la zona de vapor del Recipiente No Desmontable, y</div>\n<div>5. La descarga de la Válvula de relevo de presión se debe dirigir verticalmente en sentido ascendente.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.1"},{"id":"a7bad5e2-2d80-5c30-8e08-05719d0b3145","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":38,"identificador":"Numeral 6.2.2","contenido":"<div>6.2.2. En caso de que presente una antigüedad de fabricación igual o mayor a 10 años, debe contar con el informe y análisis de los resultados de la última evaluación de espesores y dictamen vigente de la NOM-013-SEDG-2002.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.2"},{"id":"b088a33c-3f98-51a4-87e5-2d3a18784c7a","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":39,"identificador":"Numeral 6.2.3","contenido":"<div>6.2.3. En caso de que haya sido reparado mediante aplicación de soldaduras a la sección cilíndrica o casquetes, debe contar con los informes de resultados aprobatorios de las pruebas descritas en el numeral 7.4.5.10.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.3"},{"id":"8fbd2245-f245-5314-a483-5e06a298f703","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":40,"identificador":"Numeral 6.2.4","contenido":"<div>6.2.4. En caso de que haya sido expuesto al fuego o si recibió algún impacto debido a un accidente, debe contar con los informes de resultados aprobatorios de las pruebas descritas en el numeral 7.4.5.11.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.4"},{"id":"4981cd0d-75a9-5fd8-bf83-70e0faff9c77","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":41,"identificador":"Numeral 6.2.5","contenido":"<div>6.2.5. El Regulado debe realizar y documentar una inspección visual externa del Recipiente No Desmontable, que permita:</div>\n<div>a) Evaluar las condiciones de la placa cilíndrica, cabezales y soldadura. En caso de detectar alguna de las anomalías descritas en la Tabla 1, la Unidad de Transporte no debe iniciar operaciones y se debe realizar la valoración y, en su caso, reparación correspondiente;</div>\n<div>b) Examinar los accesorios y elementos de la Unidad de Transporte para comprobar que conserven su funcionamiento y las condiciones operativas aceptables de acuerdo con la Tabla 3, y</div>\n<div>c) Reemplazar los pernos, tuercas o elementos faltantes y apretar pernos y tuercas flojos.</div>\n<div>Tabla 1- Anomalías en el Recipiente No Desmontable</div>\n<table><tbody><tr><td>Anomalía</td><td>Descripción</td></tr><tr><td>Corrosión o desgaste</td><td>Cualquier reducción visible en el espesor del material de la pared o válvula del Recipiente No Desmontable debido a picaduras, descamaciones, ranuras o reacciones químicas en la superficie del material que afecten la seguridad o capacidad de servicio.</td></tr><tr><td>Protuberancia o signos de abombado</td><td>Cualquier parte de la superficie de la sección cilíndrica, cordón de soldadura, o casquetes de un Recipiente No Desmontable, que se abulta o sobresale del resto de la superficie.</td></tr><tr><td>Abolladura</td><td>Deformación cóncava o depresión en la placa de la sección cilíndrica o casquetes del Recipiente No Desmontable sin pérdida de material con una profundidad igual o mayor a 7.0 mm; o en un cordón de soldadura con una profundidad igual o mayor a 6.35 mm.</td></tr><tr><td>Incisiones o cavidades</td><td>Marca afilada donde existe pérdida de material que ha sido removido, desplazado o redistribuido.</td></tr><tr><td>Grieta</td><td>División o separación del material que típicamente aparece de forma lineal en la superficie del Recipiente No Desmontable.</td></tr></tbody></table>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.5"},{"id":"9797290f-4799-50f3-8e29-e96b420212c1","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":42,"identificador":"Numeral 6.2.6","contenido":"<div>6.2.6. En caso de que el Recipiente No Desmontable de la Unidad de Transporte haya sido sujeto a reparación, se haya realizado una alteración de su soldadura, haya sido expuesto al fuego y/o haya tenido periodos prolongados fuera de operación con exposición interna al medio ambiente, se debe realizar una inspección visual interna para evaluar la condición de la placa cilíndrica y cabezales, detectar corrosión, abolladuras, defectos en la soldadura o desgaste; revisar la existencia y condición del Rompeolas, así como el estado de tuberías y coples al interior del Recipiente No Desmontable. La inspección visual interna debe realizarse por un laboratorio de ensayos acreditado por una Entidad de Acreditación que tenga dada de alta la inspección visual, o en su caso, por una persona certificada en inspección visual, nivel 2 conforme a la NMX-B-482-CANACERO-2016 o estándar internacional o extranjero equivalente; que señale en un informe los resultados de la misma.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.6"},{"id":"0095ab64-96d6-5e9c-b515-fa837fd001ae","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":43,"identificador":"Numeral 6.2.7","contenido":"<div>6.2.7. Si como resultado de la inspección visual externa o, en su caso, de la inspección visual interna se concluye que se requiere realizar otro ensayo no destructivo para validar la integridad del Recipiente No Desmontable para continuar en operación, éste debe realizarse y documentarse.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.7"},{"id":"5115ca11-1c63-531f-b4ab-a98f9aeb3944","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":44,"identificador":"Numeral 6.2.8","contenido":"<div>6.2.8. Se debe realizar una prueba de hermeticidad conforme a lo establecido en el numeral 7.4.5.2.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.2 · Requisitos para Auto-tanques y Semirremolques con Recipiente No Desmontable usado","seccion_nombre":"6.2.8"},{"id":"4ae1d9db-a3e9-5e80-b6e7-7d876f173ba4","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":45,"identificador":"Numeral 6.3","contenido":"<div>6.3. Expediente de integridad</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6 · Inicio de operación","seccion_nombre":"6.3"},{"id":"30145099-f2aa-5a03-93dd-e5fbe8ed231f","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":46,"identificador":"Numeral 6.3.1","contenido":"<div>6.3.1. El Regulado debe integrar un Expediente de integridad para cada Unidad de Transporte, el cual debe conservar en formato físico en sus oficinas administrativas y ser accesible para el personal operativo y/o de mantenimiento, con el objetivo de mantener registros permanentes y progresivos de la procedencia, especificaciones y condiciones de integridad del Semirremolque o Auto-tanque.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.3 · Expediente de integridad","seccion_nombre":"6.3.1"},{"id":"37cd064c-0479-5f44-bc74-6471c6c1d39f","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":47,"identificador":"Numeral 6.3.2","contenido":"<div>6.3.2. El Expediente de integridad debe indicar, como mínimo, la información de identificación siguiente:</div>\n<div>a) Identificación de la Unidad de Transporte, mediante el número de permiso otorgado por la autoridad competente en materia del Sector Hidrocarburos, número económico, marca, modelo, número de serie y número de placas;</div>\n<div>b) Número de serie del Recipiente No Desmontable, y</div>\n<div>c) Dirección de Instalación o central de resguardo donde pernocta la Unidad de Transporte autorizada por la autoridad competente en materia del Sector Hidrocarburos.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.3 · Expediente de integridad","seccion_nombre":"6.3.2"},{"id":"986141da-772f-53c2-b44c-df2fdcbd0466","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":48,"identificador":"Numeral 6.3.3","contenido":"<div>6.3.3. El Expediente de integridad debe contener los documentos siguientes:</div>\n<div>a) Ficha técnica de la Unidad de Transporte donde se especifique, entre otros datos, el peso bruto de la unidad vacía y con carga máxima, así como la capacidad del Recipiente No Desmontable al 100 % en litros de agua;</div>\n<div>b) En caso de que la Unidad de Transporte cuente con equipo de carburación de GLP, dictamen vigente de la NOM-005-SESH-2010, y</div>\n<div>c) La documentación técnica establecida en el numeral 6.1.2, 6.1.6, 6.1.7 (solo para Auto-tanques) y 6.2.1 inciso l) numeral 2, así como los informes de pruebas y ensayos realizados al Recipiente No Desmontable usado descritos en 6.2.2, 6.2.3, 6.2.4, 6.2.5, 6.2.6, 6.2.7 y 6.2.8.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.3 · Expediente de integridad","seccion_nombre":"6.3.3"},{"id":"1f9aaaf5-d75b-58e7-b051-40b5e56a2b0e","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":49,"identificador":"Numeral 6.3.4","contenido":"<div>6.3.4. El Regulado debe conservar el Expediente de integridad mientras la Unidad de Transporte forme parte de su parque vehicular y mantenerlo disponible y actualizado para cuando la Agencia lo requiera.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.3 · Expediente de integridad","seccion_nombre":"6.3.4"},{"id":"a2e53711-d6ce-5c84-b9f2-a02aaaa39b4e","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":50,"identificador":"Numeral 6.4","contenido":"<div>6.4. Dictamen de inicio de operación</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6 · Inicio de operación","seccion_nombre":"6.4"},{"id":"296e6f1e-4b2f-5799-ad80-ad6ee69a7e68","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":51,"identificador":"Numeral 6.4.1","contenido":"<div>6.4.1. El Regulado debe obtener un dictamen de inicio de operación antes de que se realice la primera carga de GLP, por cada Unidad de Transporte nueva o usada que pretenda integrarse a su parque vehicular, emitido por una unidad de inspección acreditada por una Entidad de Acreditación y aprobada por la Agencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.4 · Dictamen de inicio de operación","seccion_nombre":"6.4.1"},{"id":"9754bb17-f7bc-55be-b4db-bf70c5fcffd8","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":52,"identificador":"Numeral 6.4.2","contenido":"<div>6.4.2. El dictamen de inicio de operación debe ser integrado al Expediente de integridad de la Unidad de Transporte durante la vigencia de éste.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.4 · Dictamen de inicio de operación","seccion_nombre":"6.4.2"},{"id":"da1ac0cf-bbdc-5045-bf76-ce6ee26965a7","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":53,"identificador":"Numeral 6.4.3","contenido":"<div>6.4.3. El Regulado debe conservar el dictamen de inicio de operación para cuando la Agencia lo requiera.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.4 · Dictamen de inicio de operación","seccion_nombre":"6.4.3"},{"id":"4082b30a-ecde-57e0-9950-946a508efaf9","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":54,"identificador":"Numeral 6.4.4","contenido":"<div>6.4.4. El dictamen de inicio de operaciones no exime al Regulado de obtener los permisos y/o autorizaciones para el inicio de operaciones ante la autoridad competente.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.4 · Dictamen de inicio de operación","seccion_nombre":"6.4.4"},{"id":"aa04a648-5ecf-5e0a-b785-88b7106984a1","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":55,"identificador":"Numeral 6.4.5","contenido":"<div>6.4.5. Las Unidades de Transporte que no cuenten con un dictamen vigente de inicio de operación no deben realizar operaciones de Transporte de GLP.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.4 · Dictamen de inicio de operación","seccion_nombre":"6.4.5"},{"id":"46696a10-4849-5100-89af-6d492b04446d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":56,"identificador":"Numeral 6.4.6","contenido":"<div>6.4.6. La vigencia del dictamen de inicio de operación será de 1 año a partir de la fecha de emisión.</div>","tipo_articulo":"ordinario","titulo_nombre":"Inicio de operación","capitulo_nombre":"6.4 · Dictamen de inicio de operación","seccion_nombre":"6.4.6"},{"id":"b831bd11-e4a6-5a30-95c8-4ab85c66bc4c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":57,"identificador":"Numeral 7. Operación y mantenimiento","contenido":"<div>7. Operación y mantenimiento</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":null,"seccion_nombre":null},{"id":"76e22547-a203-5df8-874c-4fbc7ed35adb","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":58,"identificador":"Numeral 7.1","contenido":"<div>7.1. Requisitos de capacitación</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.1"},{"id":"e6dc3dca-cdfb-5961-b029-1530953c1060","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":59,"identificador":"Numeral 7.1.1","contenido":"<div>7.1.1. El Regulado debe contar con un programa anual de capacitación teórico-práctico para los operadores de Auto-tanques, conforme a lo establecido en los numerales 7.1.4 y 7.1.5, con los porcentajes de avance programado y ejecutado. Dicho programa debe incluir como mínimo los temas siguientes:</div>\n<div>a) Propiedades, riesgos y manejo seguro del GLP;</div>\n<div>b) Aspectos aplicables del Reglamento para el transporte terrestre de materiales y residuos peligrosos y de los reglamentos de tránsito locales por donde pasará la Unidad de Transporte;</div>\n<div>c) Sistema de Identificación para Unidades Destinadas al Transporte de Materiales y Residuos Peligrosos y carteles de identificación;</div>\n<div>d) Documentación a bordo de la Unidad de Transporte, conforme a lo establecido en el numeral 7.2;</div>\n<div>e) Horas de servicio del operador y estado de salud para la conducción de Unidades de Transporte de GLP y su impacto en la seguridad;</div>\n<div>f) Comportamiento de la carga en condiciones de Transporte y su relación con la estabilidad de la Unidad de Transporte;</div>\n<div>g) Manejo a la defensiva de vehículos que transportan sustancias peligrosas, identificación de ruta segura y acciones para prevenir Incidentes o Accidentes;</div>\n<div>h) Accidentes en el Transporte de GLP, consecuencias e importancia de las medidas para prevenirlos;</div>\n<div>i) Manejo de válvulas, accesorios, conexiones y cualquier otro elemento de la Unidad, así como las condiciones seguras durante la operación;</div>\n<div>j) Procedimientos operativos específicos, como mínimo los establecidos en el 7.3;</div>\n<div>k) Detección y atención a fugas de GLP;</div>\n<div>l) Revisión visual diaria;</div>\n<div>m) Uso de equipo de protección personal;</div>\n<div>n) Uso y manejo de extintores, y</div>\n<div>o) Guía o Protocolo de Respuesta a Emergencias.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.1"},{"id":"8b10d199-8249-554c-b820-f69456915be2","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":60,"identificador":"Numeral 7.1.2","contenido":"<div>7.1.2. El Regulado debe contar con los certificados de competencia laboral vigentes emitidos por el CONOCER del Estándar de Competencia EC1731 Operación del tractocamión de quinta rueda y semirremolque para Transporte de Gas L.P. vigente o aquel que lo actualice o sustituya, de cada uno de los operadores de Semirremolque.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.2"},{"id":"86e91306-3594-50fc-b1da-e8dde6a7bce7","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":61,"identificador":"Numeral 7.1.3","contenido":"<div>7.1.3. Regulado debe contar con un programa trienal de capacitación teórico-práctico por actualización para los operadores de Semirremolque, conforme a lo establecido en los numerales 7.1.4 y 7.1.5, con los porcentajes de avance programado y ejecutado. Dicho programa debe incluir como mínimo los temas siguientes:</div>\n<div>a) Comportamiento y riesgos del GLP;</div>\n<div>b) Aspectos aplicables de los reglamentos de tránsito locales por donde pasará la Unidad de Transporte;</div>\n<div>c) Riesgos en el Transporte de GLP asociados a las condiciones psicofísicas del Operador;</div>\n<div>d) Accidentes en el Transporte de GLP, consecuencias e importancia de las medidas para prevenirlos;</div>\n<div>e) Procedimientos operativos específicos, como mínimo los establecidos en el 7.3;</div>\n<div>f) Uso de equipo de protección personal;</div>\n<div>g) Uso y manejo de extintores, y</div>\n<div>h) Guía o Protocolo de Respuesta a Emergencias.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.3"},{"id":"ea6e28c8-6b8b-5b72-ac6c-af2e45a39d66","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":62,"identificador":"Numeral 7.1.4","contenido":"<div>7.1.4. La capacitación teórico-práctica de los operadores en las materias establecidas en los programas de capacitación mencionadas en los numerales 7.1.1 y 7.1.3 debe ser impartida por Agentes capacitadores externos autorizados y registrados ante la STPS que emitan una constancia oficial de competencias o habilidades laborales (DC3), así como contar con el registro del curso que imparten ante la misma autoridad.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.4"},{"id":"8a5480e4-237d-5469-a23e-f31543ee094d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":63,"identificador":"Numeral 7.1.5","contenido":"<div>7.1.5. La capacitación práctica debe realizarse mediante simuladores o en Auto-tanques y Tractocamión-Semirremolques según corresponda, en espacios controlados y seguros que permitan hacer las maniobras para las cuales se está capacitando. Las evaluaciones para constatar la capacitación adquirida deben realizarse con Autotanque o Tractocamión-Semirremolque, según corresponda.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.5"},{"id":"88b41d7f-a354-5907-b6bf-1015c2459a47","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":64,"identificador":"Numeral 7.1.6","contenido":"<div>7.1.6. El Regulado debe integrar y mantener actualizado un expediente individual de los operadores, que debe contener lo siguiente:</div>\n<div>a) Copia de la Licencia federal tipo &quot;E&quot; vigente de autotransporte federal y transporte privado de materiales y residuos peligrosos;</div>\n<div>b) Constancias oficiales de competencias o habilidades laborales (DC3), vigentes, de acuerdo con lo establecido en el numeral 7.1.1, 7.1.3 y 7.1.5, que indiquen el nombre de los operadores, las fechas de capacitación, el nombre del Agente capacitador externo que imparte la capacitación, así como documento que enliste los temas en los que se imparte la capacitación y los resultados de las evaluaciones, y</div>\n<div>c) El certificado de competencia laboral vigente en el Estándar de Competencia EC1731 Operación del tractocamión de quinta rueda y semirremolque para Transporte de Gas L.P., emitido por el CONOCER, para operadores de Semirremolques.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.6"},{"id":"06e2e996-bd7a-59aa-8ac8-610d5e7503f1","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":65,"identificador":"Numeral 7.1.7","contenido":"<div>7.1.7. Los operadores que no cuenten con las constancias oficiales de competencias o habilidades laborales (DC3) referidas en el inciso b) del numeral 7.1.6 y el certificado de competencia laboral vigente referido en el inciso c) del numeral 7.1.6, no deben operar Unidades de Transporte de GLP.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.1 · Requisitos de capacitación","seccion_nombre":"7.1.7"},{"id":"e43d0c94-cf6f-53bf-9e02-33998d570751","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":66,"identificador":"Numeral 7.2","contenido":"<div>7.2. Documentación a bordo</div>\n<div>Se debe contar con los documentos siguientes a bordo de la Unidad de Transporte:</div>\n<div>a) Licencia federal tipo &quot;E&quot; vigente;</div>\n<div>b) Copia del permiso y autorización de inicio de operaciones de la Unidad de Transporte vigente expedido por la autoridad competente en materia del Sector Hidrocarburos;</div>\n<div>c) Tarjeta de circulación vigente;</div>\n<div>d) El listado de revisión visual diaria de la Unidad de Transporte que realizó antes de la salida de la Instalación de carga para su traslado, que incluya como mínimo los elementos establecidos en el Apéndice A (Normativo);</div>\n<div>e) Hoja de Emergencia para el Transporte de Substancias, Materiales y Residuos Peligrosos, específica para GLP, o Guía de respuesta en caso de emergencia;</div>\n<div>f) Copia de la póliza del seguro vigente con las coberturas establecidas en la regulación aplicable, y</div>\n<div>g) Copia del dictamen vigente de esta Norma Oficial Mexicana de Emergencia o de la Norma Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025 según aplique.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.2"},{"id":"f5fbed46-138d-5662-b0ef-be9ded3f9b18","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":67,"identificador":"Numeral 7.3","contenido":"<div>7.3. Manual de operación y mantenimiento</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.3"},{"id":"35d06760-7b75-5184-b079-0999c6954842","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":68,"identificador":"Numeral 7.3.1","contenido":"<div>7.3.1. El Regulado debe contar con un manual de operación que incluya los procedimientos de operación desarrollados, implementados y actualizados, el cuál debe contener como mínimo lo siguiente:</div>\n<div>a) Procedimientos para las operaciones rutinarias de carga, traslado y descarga que incluya las medidas para prevenir los riesgos identificados, y</div>\n<div>b) Los procedimientos de inspección visual externa, inspección visual interna, mantenimiento y pruebas (con la frecuencia indicada en el numeral 7.4.4), y</div>\n<div>c) Los procedimientos para atención a emergencias conforme a la Hoja de Emergencia para el Transporte de Substancias, Materiales y Residuos Peligrosos, específica para GLP, o la Guía de respuesta en caso de emergencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3 · Manual de operación y mantenimiento","seccion_nombre":"7.3.1"},{"id":"6ced5c49-4446-5239-9ff7-2939666e0691","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":69,"identificador":"Numeral 7.3.1.1","contenido":"<div>7.3.1.1. Los procedimientos de operación para el Transporte de GLP deben incluir, como mínimo, los siguientes:</div>\n<div>a) Procedimiento de carga y descarga.</div>\n<div>El procedimiento de operación para la carga y descarga del Semirremolque y Auto-tanque debe establecer como mínimo los siguientes requisitos y condiciones de seguridad:</div>\n<div>1. Identificar y atender los señalamientos viales desde el ingreso hasta la salida de la Instalación de carga y descarga;</div>\n<div>2. En su caso, recibir instrucciones para la operación de transvase de acuerdo con los procedimientos de la Instalación de carga y descarga;</div>\n<div>3. Identificar la posición designada para la carga o descarga;</div>\n<div>4. Apagar el motor de la Unidad de Transporte;</div>\n<div>5. Inmovilizar el Auto-tanque o el Semirremolque, indicando acciones como: colocar el freno de mano y colocar las Calzas;</div>\n<div>6. Conectar el Auto-tanque o el Semirremolque a tierra física antes de la operación de carga o descarga;</div>\n<div>7. Revisar los indicadores de nivel, temperatura y presión y constatar que el Auto-tanque o el Semirremolque cuenta con la capacidad disponible sin exceder el 90 % en el caso del llenado, y</div>\n<div>8. De acuerdo con los procedimientos de la instalación de carga o descarga, incluir las instrucciones para auxiliar, supervisar o, en su caso realizar las operaciones de carga y descarga.</div>\n<div>b) Procedimiento de revisión visual diaria.</div>\n<div>El procedimiento de operación para la revisión visual diaria posterior a la carga del Auto-tanque o Semirremolque y previo a su salida a ruta, debe realizarse por el operador de la Unidad y debe contener como mínimo los siguientes requisitos:</div>\n<div>1. Mantener el motor apagado, colocar el freno de mano, retirar las llaves y colocar Calzas;</div>\n<div>2. Ejecutar la revisión de los elementos indicados en el Apéndice A (Normativo) y, en su caso, registrar los hallazgos en la bitácora de operación, y</div>\n<div>3. En caso de identificar algún incumplimiento en la revisión, el Auto-tanque o el Tractocamión-Semirremolque no podrá realizar el Transporte de GLP hasta ejecutar las acciones correctivas requeridas, las cuales deben registrarse en la bitácora correspondiente.</div>\n<div>c) Procedimiento para las maniobras de enganche y desenganche del Tractocamión-Semirremolque.</div>\n<div>d) Procedimiento para el traslado seguro.</div>\n<div>Se deben incluir las prácticas y recomendaciones para la conducción y control de la Unidad de Transporte, incluyendo como mínimo:</div>\n<div>1. Planificar las rutas previo a la salida y establecer las acciones que debe atender el Operador ante eventos que podrían afectar la seguridad de las operaciones, incluyendo los derivados de la infraestructura vial (vías primarias, secundarias, de acceso controlado y factores de relieve), fuentes de ignición, obstrucciones, maniobras a realizar por el Operador, iluminación, señalización, intersecciones en la ruta, curvas, límites de altura, peso y dimensiones, lugares de concentración pública, densidad poblacional, factores naturales y climatológicos (lluvias fuertes, vientos fuertes, neblina, granizo, heladas, tormentas eléctricas, sismos, derrumbes, deslaves, inundaciones, entre otros particulares de la zona geográfica de la ruta de Transporte), factores socio-organizativos como bloqueos, manifestaciones, amenazas y sabotajes;</div>\n<div>2. Mantener la distancia con otros vehículos;</div>\n<div>3. Encender los faros;</div>\n<div>4. Respetar los límites de velocidad y reglamento de tránsito aplicable;</div>\n<div>5. Considerar durante la conducción el peso de la carga y el centro de gravedad del Auto-tanque o Semirremolque;</div>\n<div>6. Realizar el cambio de velocidades de manera gradual y el cambio de dirección de forma controlada y planeada;</div>\n<div>7. Considerar un espacio de al menos 6 segundos respecto al vehículo que este delante para el frenado seguro y 1 segundo adicional por cada condición adversa que se presente tales como: neblina, lluvia, piso mojado, grava suelta u obra en proceso;</div>\n<div>8. Recuperar el control del vehículo antes de realizar cualquier cambio de dirección o velocidad;</div>\n<div>9. Identificar los puntos ciegos a los lados y en la parte trasera. Considerar los puntos ciegos siempre que retroceda el vehículo para evitar colisiones;</div>\n<div>10. Revisar los espejos con frecuencia, usar las señales de giro y mantener la Unidad de Transporte dentro del carril asignado para su circulación;</div>\n<div>11. En caso de detectar defectos o deficiencias que afecten la operación o alguna avería mecánica durante el traslado y operaciones de la Unidad de Transporte, el operador debe registrar en la bitácora los hallazgos detectados. La Unidad de Transporte no se debe operar hasta constatar que los hallazgos fueron reparados. En el caso de Tractocamión-Semirremolque, si la avería mecánica fue en el Tractocamión, se podrá emplear otro Tractocamión que cuente con el dictamen aprobatorio vigente de cumplimiento con la NOM-068-SCT-2-2014, para continuar el traslado; en ningún caso la Unidad de Transporte debe ser remolcada por una grúa con GLP a bordo;</div>\n<div>12. No realizar operaciones de transvase de Gas Licuado de Petróleo fuera de las Instalaciones reguladas destinadas para tal fin, ni durante la ruta;</div>\n<div>13. No realizar purgas ni venteos durante la ruta, a menos que sea una situación de riesgo, para lo cual se deberá actuar de acuerdo con lo previsto en la &quot;Guía o protocolo de respuesta en caso de emergencia&quot;;</div>\n<div>14. No realizar paradas que no estén contempladas en la ruta, ni circular por áreas centrales de ciudades y poblados; por lo que será preferible utilizar los libramientos periféricos cuando éstos existan;</div>\n<div>15. No circular en convoy;</div>\n<div>16. No fumar o encender fuego;</div>\n<div>17. No estacionarse ni circular cerca de fuego abierto o de incendio;</div>\n<div>18. No circular por carriles centrales y segundos niveles de las vías de acceso controlado;</div>\n<div>19. No utilizar dispositivos electrónicos móviles, y</div>\n<div>20. Solo se podrá realizar transvase en las instalaciones destinadas para tal fin, en los términos de lo establecido en la Ley del Sector Hidrocarburos y su Reglamento.</div>\n<div>e) Procedimiento de limpieza del Recipiente No Desmontable.</div>\n<div>El procedimiento de operación para la limpieza del Recipiente No Desmontable debe ser específico y acorde con las características de peligrosidad del GLP, y debe establecer como mínimo los siguientes requisitos:</div>\n<div>1. Indicar el equipo de protección personal requerido para las actividades;</div>\n<div>2. Identificar las condiciones y medidas de seguridad requeridas para llevar a cabo la remoción de remanentes o residuos contenidos en el Recipiente No Desmontable del Auto-tanque o Semirremolque, sus accesorios y dispositivos de seguridad;</div>\n<div>3. Especificar el procedimiento de despresurización, vaciado, purgado e inertizado;</div>\n<div>4. Verificar las condiciones existentes en el interior del Recipiente No Desmontable antes, durante y al final de la limpieza, monitoreando la concentración de oxígeno, nivel de inflamabilidad o explosividad;</div>\n<div>5. Indicar las medidas para el manejo y control de los efluentes, así como el manejo de los residuos sólidos provenientes del proceso de limpieza, y</div>\n<div>6. Si las actividades de limpieza se realizan en las instalaciones de un tercero, el Regulado debe obtener el documento que acredite que la limpieza y control de remanentes se realizó de conformidad con la NOM-019-SCT2/2015.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3.1 · El Regulado debe contar con un manual de operación que incluya los procedimientos de operación desarrollados, implementados y actualizados, el cuál debe contener como mínimo lo siguiente:","seccion_nombre":"7.3.1.1"},{"id":"700081b4-add9-5e38-9d5d-24c4bbd4e426","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":70,"identificador":"Numeral 7.3.1.2","contenido":"<div>7.3.1.2. Los procedimientos de operación deben indicar las acciones a seguir por el operador en caso de fallas mecánicas o eléctricas en el sistema automotriz o fugas en la Unidad de Transporte.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3.1 · El Regulado debe contar con un manual de operación que incluya los procedimientos de operación desarrollados, implementados y actualizados, el cuál debe contener como mínimo lo siguiente:","seccion_nombre":"7.3.1.2"},{"id":"41ba78ec-6a23-58a3-8825-cf67900a9df7","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":71,"identificador":"Numeral 7.3.1.3","contenido":"<div>7.3.1.3. Los procedimientos de operación deben estar documentados y ser difundidos al personal responsable de las actividades.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3.1 · El Regulado debe contar con un manual de operación que incluya los procedimientos de operación desarrollados, implementados y actualizados, el cuál debe contener como mínimo lo siguiente:","seccion_nombre":"7.3.1.3"},{"id":"3243b2eb-c3cd-5faf-8b6f-f7e16591a4a5","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":72,"identificador":"Numeral 7.3.1.4","contenido":"<div>7.3.1.4. Los procedimientos de operación deben permanecer en la Unidad de Transporte o, en su caso, una lista de verificación o instructivo simplificado e ilustrado de la secuencia de las operaciones a cargo del operador de la Unidad de Transporte.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3.1 · El Regulado debe contar con un manual de operación que incluya los procedimientos de operación desarrollados, implementados y actualizados, el cuál debe contener como mínimo lo siguiente:","seccion_nombre":"7.3.1.4"},{"id":"7e105af6-a6e8-532b-8892-8f23da627c09","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":73,"identificador":"Numeral 7.3.2","contenido":"<div>7.3.2. El Regulado debe contar con un programa de mantenimiento preventivo del Recipiente No Desmontable, válvulas y accesorios de la Unidad de Transporte, así como de sus inspecciones y pruebas, que incluya para cada elemento, dispositivo o sistema, el tipo de mantenimiento, inspección o prueba que se realizará, la actividad a realizar, las fechas programadas para cada actividad, los criterios de aceptación o rechazo y el personal competente necesario para cada actividad que se llevará a cabo en el año calendario.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3 · Manual de operación y mantenimiento","seccion_nombre":"7.3.2"},{"id":"f2c892d4-6246-55df-836b-45c8b98c62f0","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":74,"identificador":"Numeral 7.3.3","contenido":"<div>7.3.3. Se debe ejecutar y demostrar el cumplimiento del programa de mantenimiento, registrando en la bitácora de operación y mantenimiento las fechas de inicio y término de las actividades de mantenimiento.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.3 · Manual de operación y mantenimiento","seccion_nombre":"7.3.3"},{"id":"2e2d9a73-f461-58dd-bd9c-e941dd1b57f9","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":75,"identificador":"Numeral 7.4","contenido":"<div>7.4. Integridad del Recipiente No Desmontable del Semirremolque y Auto-tanque</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.4"},{"id":"a9aa86e1-c255-59bd-9a70-6dfd9db9b3e3","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":76,"identificador":"Numeral 7.4.1","contenido":"<div>7.4.1. Antes de realizar cualquier actividad de inspección visual, mantenimiento o pruebas, se deben revisar los registros de los resultados previos del Recipiente No Desmontable y reparaciones previstas.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4 · Integridad del Recipiente No Desmontable del Semirremolque y Auto-tanque","seccion_nombre":"7.4.1"},{"id":"f0dd0408-c21e-55e7-a202-fe558100cae1","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":77,"identificador":"Numeral 7.4.2","contenido":"<div>7.4.2. Antes de realizar la inspección visual interna, pruebas o reparaciones al interior del Recipiente No Desmontable, éste se debe drenar, purgar, limpiar e inertizar de acuerdo con el procedimiento establecido en el numeral 7.3.1.1, inciso e).</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4 · Integridad del Recipiente No Desmontable del Semirremolque y Auto-tanque","seccion_nombre":"7.4.2"},{"id":"b6594947-7b46-5a00-a663-be81593f5a4f","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":78,"identificador":"Numeral 7.4.3","contenido":"<div>7.4.3. Durante las actividades de inspección visual, mantenimiento o pruebas del Recipiente No Desmontable, se debe cumplir lo siguiente:</div>\n<div>a) El personal debe ser competente en el manejo del GLP y, en su caso, tener conocimiento de las medidas de seguridad para trabajos en espacios confinados de acuerdo con la NOM-033-STPS-2015;</div>\n<div>b) Las herramientas, equipos y elementos de protección personal se deben revisar antes de ser usados en las actividades de inspección visual o mantenimiento, y</div>\n<div>c) El personal que realice las pruebas debe usar el equipo de protección personal específico para la actividad que realiza.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4 · Integridad del Recipiente No Desmontable del Semirremolque y Auto-tanque","seccion_nombre":"7.4.3"},{"id":"3fd02caa-201e-5789-a29b-971a3f46bb1c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":79,"identificador":"Numeral 7.4.4","contenido":"<div>7.4.4. Se deben realizar como mínimo las pruebas e inspecciones periódicas, como parte del programa de inspecciones y pruebas, indicadas en la Tabla 2 para monitorear las condiciones del Recipiente No Desmontable.</div>\n<div>Tabla 2- Pruebas e inspecciones periódicas del Recipiente No Desmontable</div>\n<table><tbody><tr><td>Prueba/inspección</td><td>Periodicidad</td></tr><tr><td>Inspección visual externa</td><td>Anual</td></tr><tr><td>Prueba de hermeticidad</td><td>Anual</td></tr><tr><td>Prueba hidrostática</td><td>Cada 10 años a partir de su fecha de fabricación.</td></tr><tr><td>Evaluación de espesores mediante medición ultrasónica</td><td>A los 10 años contados a partir de la fecha de fabricación y posteriormente cada 5 años.</td></tr></tbody></table>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4 · Integridad del Recipiente No Desmontable del Semirremolque y Auto-tanque","seccion_nombre":"7.4.4"},{"id":"c37568d0-7d5b-5bec-a23e-67827c9e4de1","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":80,"identificador":"Numeral 7.4.5","contenido":"<div>7.4.5. Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4 · Integridad del Recipiente No Desmontable del Semirremolque y Auto-tanque","seccion_nombre":"7.4.5"},{"id":"d994e943-8fcf-534e-9346-8331bd8836b5","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":81,"identificador":"Numeral 7.4.5.1","contenido":"<div>7.4.5.1. Inspección visual externa</div>\n<div>a) Evaluar las condiciones de la placa cilíndrica, cabezales y soldadura. En caso de detectar alguna de las anomalías descritas en la Tabla 1, el Auto-tanque o Semirremolque debe ser puesto fuera de servicio para realizar la valoración y, en su caso, reparación correspondiente;</div>\n<div>b) Examinar la condición de las tuberías, válvulas, acoplamientos y coples para detectar corrosión, defectos en soldaduras y fugas; así como las condiciones referidas en la Tabla 3;</div>\n<div>c) Reemplazar los pernos, tuercas o elementos faltantes y apretar pernos y tuercas flojos, así como monitorearlos marcando una línea para verificar su afloje registrando mensualmente su desplazamiento;</div>\n<div>d) Revisar que el Recipiente No Desmontable conserva la placa de datos con la información de diseño y fabricación legibles conforme a lo establecido en el numeral 6.1.1, y</div>\n<div>e) La Inspección visual externa debe realizarse por personal capacitado en las actividades de inspección y mantenimiento; y este debe documentar el resultado de la misma.</div>\n<div>Tabla 3- Condiciones operativas aceptables de elementos y accesorios del Auto-tanque y Tractocamión- Semirremolque</div>\n<table><tbody><tr><td>Elemento</td><td>Actividad de revisión</td><td>Criterios de aceptación</td></tr><tr><td>Válvula de relevo de presión</td><td>Inspección visual</td><td>Cuenta con la fecha de fabricación legible en el cuerpo de la válvula. Presenta una antigüedad menor de diez años a partir de su fecha de fabricación, o en su caso, una antigüedad menor a la recomendada por el fabricante en su certificado de fabricación. Está exenta de fisuras, rupturas, obstrucciones o daños. Está libre de cualquier señal de manipulación o reajuste. Está protegida por un tapón de hule y/o capuchón. Está libre de humedad y partículas.</td></tr><tr><td>Válvula de exceso de flujo</td><td>Inspección visual</td><td>Cuenta con la fecha de fabricación legible en el cuerpo de la válvula. Presenta una antigüedad menor de diez años a partir de su fecha de fabricación, o en su caso, una antigüedad menor a la recomendada por el fabricante en su certificado de fabricación. Está exenta de fisuras, rupturas, obstrucciones o daños.</td></tr><tr><td>Válvula de no retroceso</td><td>Inspección visual</td><td>Cuenta con la fecha de fabricación legible en el cuerpo de la válvula. Presenta una antigüedad menor de diez años a partir de su fecha de fabricación, o en su caso, una antigüedad menor a la recomendada por el fabricante en su certificado de fabricación. Está exenta de fisuras, rupturas, obstrucciones o daños.</td></tr><tr><td>Válvula de llenado</td><td>Inspección visual</td><td>Cuenta con la fecha de fabricación legible en el cuerpo de la válvula. Presenta una antigüedad menor de diez años a partir de su fecha de fabricación, o en su caso, una antigüedad menor a la recomendada por el fabricante en su certificado de fabricación. Está exenta de fisuras, rupturas, obstrucciones o daños.</td></tr><tr><td>Indicador de nivel</td><td>Inspección visual</td><td>Cuenta con carátula legible. Con la aguja en funcionamiento.</td></tr><tr><td>Manómetro de presión</td><td>Inspección visual</td><td>Presenta una antigüedad menor a 10 años a partir de su fecha de fabricación o, en su caso, una antigüedad menor a la recomendada por el fabricante en su certificado de fabricación Cuenta con carátula legible. Con la aguja en funcionamiento.</td></tr><tr><td>Termómetro</td><td>Inspección visual</td><td>Cuenta con carátula legible y con la aguja en funcionamiento.</td></tr><tr><td>Conexiones</td><td>Inspección visual</td><td>Permanecen firmemente aseguradas sin signos de deterioro o fisuras.</td></tr><tr><td>Tuberías</td><td>Inspección visual que incluya pernos, conexiones y sellos.</td><td>Permanecen firmemente soportadas y sin movimiento o desplazamiento.</td></tr><tr><td>Entrada pasa-hombre</td><td>Inspección visual</td><td>Permanece con su tornillería completa, sin corrosión.</td></tr><tr><td>Conectores flexibles</td><td>Inspección visual</td><td>Cuenta con recubrimiento sin signos de cortes, abrasiones, desgaste o cualquier otro daño en el recubrimiento que deje expuesta la malla interna. Se debe sustituir al cumplir 5 años a partir de su fecha de fabricación. Su longitud es igual o menor a 1 m.</td></tr><tr><td>Señales y avisos</td><td>Inspección visual.</td><td>Son legibles y cumplen con lo establecido en el numeral 6.1.4.</td></tr><tr><td>Extintor</td><td>Inspección visual.</td><td>Cuentan con capacidad de al menos 9 kg de polvo químico seco tipo ABC. La aguja del manómetro está dentro de la zona de operación. La manguera está limpia, sin obstrucciones, cortes, cuarteaduras y acoplada firmemente. Cuenta con el seguro. Está libre de corrosión o superficies rugosas, obstrucción, golpes o deformaciones. Cuenta con etiqueta de servicio y caducidad vigente.</td></tr><tr><td>Lámpara de mano, Calzas, señales reflejantes para carretera, medidor de presión para las llantas</td><td>Inspección visual</td><td>Se encuentran a bordo de la Unidad de Transporte, operables y sin daños que comprometan su funcionamiento.</td></tr><tr><td>Cinta estática</td><td>Inspección visual</td><td>Está firmemente sujeta y hace contacto con el suelo.</td></tr></tbody></table>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.1"},{"id":"2e75490b-1eb7-55ee-bd2e-f7ce5bedac86","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":82,"identificador":"Numeral 7.4.5.2","contenido":"<div>7.4.5.2. Prueba de hermeticidad</div>\n<div>a) La prueba de hermeticidad se realiza con GLP a un nivel de llenado de entre 85% y 90% de la capacidad nominal del Recipiente No Desmontable; si por la temperatura del sitio en donde se lleva a cabo la prueba de hermeticidad el máximo llenado se encuentra por debajo del 85%, se debe realizar la prueba a dicho nivel documentando la causa, la presión del Recipiente No Desmontable y la temperatura del sitio en el que se realizó la prueba. La prueba debe mantenerse durante al menos 5 min y posteriormente corroborar la ausencia de fugas tanto en el Recipiente No Desmontable como en la válvula de relevo de presión, en la válvula de exceso de flujo, en la válvula de no retroceso, en la válvula de llenado, en la válvula de máximo llenado, en el indicador de nivel, en el termómetro, en las conexiones, en las tuberías y en la entrada pasa-hombre.</div>\n<div>b) La prueba de hermeticidad debe realizarse por personal capacitado en presencia de una unidad de inspección acreditada por una entidad de acreditación y aprobada por la Agencia; o en su caso, por un laboratorio de ensayos acreditado por una Entidad de Acreditación que tenga dada de alta la prueba de hermeticidad o, en su caso, por una persona certificada en prueba de hermeticidad, nivel 2 conforme a la NMX-B-482-CANACERO-2016 o estándar internacional o extranjero equivalente; que indique en un informe los resultados de esta.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.2"},{"id":"776fa93f-68da-529c-8d6a-56cb5c220f18","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":83,"identificador":"Numeral 7.4.5.3","contenido":"<div>7.4.5.3. Inspección visual interna</div>\n<div>a) Cuando aplique, se debe realizar una inspección visual interna del Recipiente No Desmontable del Auto-tanque o Semirremolque para evaluar la condición de la placa cilíndrica y cabezales, detectar corrosión, abolladuras, defectos en la soldadura o desgaste; revisar la existencia y condición del Rompeolas, así como el estado de tuberías y coples al interior del Recipiente No Desmontable;</div>\n<div>b) La inspección visual interna debe realizarse por un laboratorio de ensayos acreditado por una Entidad de Acreditación que tenga dada de alta la inspección visual o, en su caso, por una persona certificada en inspección visual, nivel 2 conforme a la NMX-B-482-CANACERO-2016 o estándar internacional o extranjero equivalente; que señale en un informe los resultados de esta, y</div>\n<div>c) Si como resultado de la inspección visual externa y de la inspección visual interna se concluye que se requiere realizar otro ensayo no destructivo para validar la integridad del Recipiente No Desmontable para continuar en operación, este debe realizarse y documentarse.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.3"},{"id":"9d3616e7-4911-5a82-9fa3-dcc4d30e8083","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":84,"identificador":"Numeral 7.4.5.4","contenido":"<div>7.4.5.4. Prueba hidrostática</div>\n<div>a) El Recipiente No Desmontable se debe llenar con agua a una temperatura que no exceda 35 ºC y a una presión hidrostática de 1.3 veces su presión de diseño como mínimo, que en ningún caso debe exceder el 90 % del esfuerzo límite de cedencia del material. El Recipiente No Desmontable debe mantener la presión de prueba durante al menos 10 min, para detectar fugas, abombamientos o cualquier otro defecto, y</div>\n<div>b) La prueba hidrostática debe realizarse por un laboratorio de ensayos acreditado por una Entidad de Acreditación que tenga dada de alta la prueba hidrostática, que indique en un informe los resultados de ésta.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.4"},{"id":"d8121c63-bb00-59a9-a1e2-893226332e4b","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":85,"identificador":"Numeral 7.4.5.5","contenido":"<div>7.4.5.5. Evaluación de espesores mediante medición ultrasónica</div>\n<div>Se debe realizar la evaluación de espesores mediante medición ultrasónica de la sección cilíndrica y casquetes del Recipiente No Desmontable de conformidad con la NOM-013-SEDG-2002.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.5"},{"id":"082e8508-e00c-51fa-a426-2a0f2817b513","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":86,"identificador":"Numeral 7.4.5.6","contenido":"<div>7.4.5.6. Cualquier área del Recipiente No Desmontable que muestre evidencia de abolladuras, grietas, hendiduras, incisiones o cavidades externas o corrosión, debe someterse como mínimo a una evaluación de espesores mediante medición ultrasónica realizada por una unidad de inspección acreditada por una Entidad de Acreditación y aprobada en la NOM-013-SEDG-2002.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.6"},{"id":"fde1ad69-b77b-56a9-8d5c-f353d6687ed8","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":87,"identificador":"Numeral 7.4.5.7","contenido":"<div>7.4.5.7. En caso de detectar defectos en la soldadura como grietas, orificios, fusión incompleta o defectos estructurales, el Recipiente No Desmontable se debe poner fuera de servicio para efectuar la reparación correspondiente.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.7"},{"id":"9d73a18f-f240-5de9-9721-e60800f74d3c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":88,"identificador":"Numeral 7.4.5.8","contenido":"<div>7.4.5.8. Las reparaciones al Recipiente No Desmontable que requieran soldadura o que afecten su integridad estructural debe realizarse por un fabricante certificado en la NOM-009-SESH-2011 o aquella que la sustituya.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.8"},{"id":"2c346245-c9b7-5440-9d73-3aa539b07686","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":89,"identificador":"Numeral 7.4.5.9","contenido":"<div>7.4.5.9. Cuando, como resultado de un mantenimiento, se repare o reemplace algún elemento como tuberías, válvulas, mangueras o accesorios sin haber realizado trabajos de corte y soldadura en la pared del cuerpo o cabezas del Recipiente No Desmontable, se debe realizar la prueba de hermeticidad de los elementos reparados o reemplazados posterior a su instalación en el Recipiente No Desmontable.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.9"},{"id":"1e869a12-e28e-522a-98fa-5f2b6f132b0f","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":90,"identificador":"Numeral 7.4.5.10","contenido":"<div>7.4.5.10. Si el Recipiente No Desmontable fue sujeto a reparación o alteración de su soldadura, o se soldaron partes directamente al cuerpo o cabezas, se debe efectuar el tratamiento térmico y, como mínimo, las pruebas siguientes:</div>\n<div>a) Inspección visual interna;</div>\n<div>b) Prueba radiográfica al 100 % de la soldadura aplicada en la reparación;</div>\n<div>c) Prueba hidrostática, y</div>\n<div>d) Prueba de hermeticidad.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.10"},{"id":"e5960fad-13d7-5254-9c1b-b9a2c9747588","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":91,"identificador":"Numeral 7.4.5.11","contenido":"<div>7.4.5.11. En caso de que el Recipiente No Desmontable haya estado expuesto al fuego, se debe efectuar el tratamiento térmico y, como mínimo, las pruebas siguientes:</div>\n<div>a) Inspección visual interna;</div>\n<div>b) Evaluación de espesores mediante medición ultrasónica;</div>\n<div>c) Prueba radiográfica en el 100 % de las soldaduras del área afectada;</div>\n<div>d) Dureza de materiales, como mínimo, en 6 puntos del área afectada;</div>\n<div>e) Réplicas metalográficas, como mínimo, en 4 puntos del área afectada, y</div>\n<div>f) Prueba hidrostática.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.11"},{"id":"86b68692-fbac-54f6-8a38-4056b7a600db","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":92,"identificador":"Numeral 7.4.5.12","contenido":"<div>7.4.5.12. La prueba radiográfica debe realizarse por personas que estén acreditadas bajo la NMX-B-482-CANACERO-2016.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.12"},{"id":"9d364e65-d901-5df9-9c04-46ffbc6bb2c6","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":93,"identificador":"Numeral 7.4.5.13","contenido":"<div>7.4.5.13. Las pruebas de dureza de materiales y réplicas metalográficas deben ser realizadas por laboratorios de ensayos acreditados por una Entidad de Acreditación.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.13"},{"id":"119ae06e-ec8b-5532-9d1b-a3c2740fc88f","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":94,"identificador":"Numeral 7.4.5.14","contenido":"<div>7.4.5.14. En caso de que el Recipiente No Desmontable haya tenido periodos prolongados fuera de operación con exposición interna al medio ambiente, se debe efectuar una inspección visual interna conforme a lo establecido en el numeral 7.4.5.3.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.14"},{"id":"75bf4dfe-bdce-55d6-b9bb-c7e9251b5e8a","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":95,"identificador":"Numeral 7.4.5.15","contenido":"<div>7.4.5.15. Con el resultado de las pruebas, se debe determinar si el recipiente se encuentra dentro de los parámetros aceptables para continuar operando. Los documentos que contengan los resultados de las pruebas se deben integrar al Expediente de integridad.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.15"},{"id":"6c5c2448-3c42-5020-a66c-1519e510bef4","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":96,"identificador":"Numeral 7.4.5.16","contenido":"<div>7.4.5.16. Se debe realizar el mantenimiento preventivo de los accesorios y elementos del Auto-tanque o Semirremolque para comprobar que conserven su funcionamiento y las condiciones operativas establecidas en la presente Norma Oficial Mexicana de Emergencia y las recomendadas por el fabricante.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.16"},{"id":"22414100-206d-543d-aba9-672a77de904c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":97,"identificador":"Numeral 7.4.5.17","contenido":"<div>7.4.5.17. Cada informe de prueba o inspección visual debe incluir la siguiente información, según corresponda:</div>\n<div>a) Tipo de prueba o inspección visual realizada;</div>\n<div>b) Fecha de la prueba o inspección visual (mes y año);</div>\n<div>c) Listado de todos los elementos probados o inspeccionados;</div>\n<div>d) Ubicación de los defectos encontrados y método de reparación;</div>\n<div>e) Certificado, acreditación o registro de la persona física o moral que realiza las reparaciones;</div>\n<div>f) Nombre y dirección de la persona que realiza la prueba, y</div>\n<div>g) Firma del inspector y del operador o personal responsable designado por el Regulado.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.4.5 · Las pruebas referidas en el numeral 7.4.4 deben cumplir respectivamente con lo siguiente:","seccion_nombre":"7.4.5.17"},{"id":"8be3b0fc-0917-56e4-b360-80bbb0e37b9d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":98,"identificador":"Numeral 7.5","contenido":"<div>7.5. Bitácoras y expediente de Integridad</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.5"},{"id":"6baa1f8c-c7a5-58ac-9ace-4d2af1416890","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":99,"identificador":"Numeral 7.5.1","contenido":"<div>7.5.1. Se debe contar con uno o varios libros de bitácoras foliadas y/o bitácoras electrónicas mediante aplicaciones de software, para el registro de las actividades de operación y mantenimiento, fecha en que se llevaron a cabo, resultado, acciones requeridas, así como el personal responsable de ejecutar las actividades. Las bitácoras deben cumplir como mínimo con los siguientes requisitos:</div>\n<div>a) Los registros en la bitácora no deben ser alterados y en caso de requerirse alguna corrección, esta debe ser a través de un nuevo registro;</div>\n<div>b) El o los libros de bitácoras deben estar disponibles en un lugar de fácil acceso tanto para el operador de la Unidad de Transporte como para el personal responsable del mantenimiento;</div>\n<div>c) Cada libro de bitácora debe contener como mínimo los datos de: número de permiso otorgado por la autoridad competente en materia del Sector Hidrocarburos, denominación o razón social del Regulado, número económico de la Unidad de Transporte y nombre del o los operadores o del personal de mantenimiento, según sea el caso;</div>\n<div>d) En caso de usar bitácoras electrónicas mediante aplicaciones de software para el registro de las actividades de operación y mantenimiento de la Unidad de Transporte, deben cumplir con lo siguiente:</div>\n<div>1. Permitir la rastreabilidad de las actividades y los registros de operación y mantenimiento;</div>\n<div>2. El ingreso a la aplicación de software debe estar limitado por medio de un nombre de usuario y contraseña;</div>\n<div>3. Para cada registro en bitácora, la aplicación de software debe incluir automáticamente hora, fecha y nombre de la persona o nombre de usuario que realiza el registro;</div>\n<div>4. La aplicación de software debe almacenar todos los registros y no permitir que éstos sean eliminados, y</div>\n<div>5. Todos los registros deben estar disponibles en cualquier momento en un equipo de cómputo o dispositivos móviles.</div>\n<div>e) Los registros en los libros de bitácoras de las actividades de operación deben conservarse por el Regulado por al menos 1 año, o hasta la siguiente Evaluación de la Conformidad, y</div>\n<div>f) Los registros en los libros de bitácoras de las actividades de mantenimiento, inspecciones y pruebas deben conservarse por el Regulado hasta el siguiente mantenimiento, inspección o prueba del mismo tipo que se realice a la Unidad de Transporte.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.5 · Bitácoras y expediente de Integridad","seccion_nombre":"7.5.1"},{"id":"4591fe2a-39c5-5aa6-a735-13d5a835a597","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":100,"identificador":"Numeral 7.5.2","contenido":"<div>7.5.2. El Regulado debe conservar e integrar al Expediente de integridad el certificado de fabricación del recipiente No Desmontable, así como los informes de prueba e inspecciones, mantenimientos realizados y certificados de calibración de instrumentos, hasta que se complete con éxito la siguiente prueba, inspección visual, mantenimiento o calibración del mismo tipo. El expediente de integridad debe estar identificado para cada Unidad con la información señalada en el numeral 6.3.2.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.5 · Bitácoras y expediente de Integridad","seccion_nombre":"7.5.2"},{"id":"11aceda2-ff62-5ebc-ae3d-edc769f21be4","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":101,"identificador":"Numeral 7.5.3","contenido":"<div>7.5.3. Se debe contar anualmente con el dictamen aprobatorio vigente de cumplimiento con la NOM-068-SCT-2-2014 para cada Semirremolque y Auto-tanque. Dicho dictamen vigente deben ser integrado al Expediente de integridad. Cualquier Tractocamión que se utilice en articulación con el Semirremolque para realizar el Transporte de GLP debe contar con el dictamen vigente de cumplimiento de la NOM-068-SCT-2-2014.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.5 · Bitácoras y expediente de Integridad","seccion_nombre":"7.5.3"},{"id":"7e707780-fb6a-5bbf-b764-7d624e010229","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":102,"identificador":"Numeral 7.5.4","contenido":"<div>7.5.4. El Tractocamión y el Auto-tanque deben contar con un gobernador de velocidad, a través de la computadora del motor o bien en el caso de las Unidades que no cuenten con computadora en el motor, a través de un accionador electromecánico del pedal de frenado; en ambos casos, a efecto de que se restrinja su velocidad hasta un máximo de 80 km/h y contar con el documento que acredite su instalación. En el caso de los Auto-tanques el documento debe ser integrado al Expediente de integridad; en el caso del los Tractocamiones, el documento debe ser conservado mientras estos formen parte de su parque vehicular y debe estar disponible para cuando la Agencia lo requiera.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.5 · Bitácoras y expediente de Integridad","seccion_nombre":"7.5.4"},{"id":"b446db4d-d62b-5c22-8bb8-8d89ad8c5f1a","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":103,"identificador":"Numeral 7.5.5","contenido":"<div>7.5.5. El expediente de integridad de las Unidades de Transporte debe conservarse por el Regulado mientras estas estén adscritas a su parque vehicular y debe estar disponible para cuando la Agencia lo requiera.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.5 · Bitácoras y expediente de Integridad","seccion_nombre":"7.5.5"},{"id":"832ca2c4-4ead-55e9-ba9d-e37570a4a27e","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":104,"identificador":"Numeral 7.6","contenido":"<div>7.6. El Regulado debe contar con la siguiente información, mientras las unidades se encuentren adscritas a su parque vehicular, para cuando la Agencia lo requiera:</div>\n<div>a) Listado actual de Auto-tanques de Transporte en operación, que incluya por Unidad:</div>\n<div>1. Número de permiso y autorización otorgado por la autoridad competente en materia del Sector Hidrocarburos;</div>\n<div>2. Número de serie o número único de identificación del Recipiente No Desmontable y capacidad nominal en litros de agua;</div>\n<div>3. Marca, modelo, número de serie, número de placas y número económico de la parte motriz;</div>\n<div>4. Número o identificación del dictamen vigente inicio de operación o de operación y mantenimiento, según corresponda, nombre de la unidad de inspección que lo emitió y fecha de emisión, y</div>\n<div>5. Fecha de emisión del último dictamen aprobatorio obtenido de la NOM-068-SCT-2-2014.</div>\n<div>b) Listado actual de Semirremolques y Tractocamiones de Transporte en operación, que incluya por Unidad:</div>\n<div>1. Número de permiso y autorización otorgado por la autoridad competente en materia del Sector Hidrocarburos;</div>\n<div>2. Número de serie o número único de identificación del Recipiente No Desmontable y capacidad nominal en litros de agua;</div>\n<div>3. Número de identificación vehicular, placas y, en su caso, número económico, del Semirremolque;</div>\n<div>4. Marca, modelo, número de serie, número de placas, en su caso número económico y fecha de emisión del último dictamen aprobatorio obtenido de la NOM-068-SCT-2-2014 del Tractocamión, y</div>\n<div>5. Número o identificación del dictamen vigente de esta Norma Oficial Mexicana de Emergencia o de la Norma Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025 del Semirremolque, nombre de la unidad de inspección que lo emitió y fecha de emisión.</div>\n<div>c) Listado actual de operadores de sus Unidades de Transporte, que indique el nombre completo;</div>\n<div>d) Listado actual de Instalaciones o centrales de resguardo autorizadas donde pernoctan sus Unidades de Transporte, que indique la dirección completa de su ubicación, y</div>\n<div>e) Registro de las rutas de origen y destino que realizan sus Unidades de Transporte de GLP. El Regulado debe mantener el histórico de esta información del último año.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.6"},{"id":"04872a91-8083-5eed-a58f-2c19cca2aa33","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":105,"identificador":"Numeral 7.7","contenido":"<div>7.7. Dictamen de operación y mantenimiento</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7 · Operación y mantenimiento","seccion_nombre":"7.7"},{"id":"6475b1d1-e334-5dd2-8f1d-5e4913308587","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":106,"identificador":"Numeral 7.7.1","contenido":"<div>7.7.1. El Regulado debe obtener anualmente, a partir del primer año de inicio de operaciones, un dictamen de operación y mantenimiento, emitido por una unidad de inspección acreditada por una Entidad de Acreditación y aprobada por la Agencia, en el que conste que cada Unidad de Transporte cumple con los requisitos establecidos en el capítulo 7. Operación y mantenimiento. El dictamen de operación y mantenimiento debe ser integrado al Expediente de integridad durante la vigencia de éste.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.7 · Dictamen de operación y mantenimiento","seccion_nombre":"7.7.1"},{"id":"4f73fb92-86f2-5816-9ffc-bc55b54cac47","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":107,"identificador":"Numeral 7.7.2","contenido":"<div>7.7.2. El Regulado debe conservar el dictamen de operación y mantenimiento para cuando la Agencia lo requiera.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.7 · Dictamen de operación y mantenimiento","seccion_nombre":"7.7.2"},{"id":"2beb985a-7afb-5083-979e-a949b1d20f27","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":108,"identificador":"Numeral 7.7.3","contenido":"<div>7.7.3. Las Unidades de Transporte que no cuenten con un dictamen vigente de operación y mantenimiento no deben realizar operaciones de Transporte de GLP.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.7 · Dictamen de operación y mantenimiento","seccion_nombre":"7.7.3"},{"id":"381f8218-469c-57f0-9832-20c44f62b724","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":109,"identificador":"Numeral 7.7.4","contenido":"<div>7.7.4. El Dictamen de operación y mantenimiento será válido siempre y cuando la Unidad de Transporte sea operada por el personal que haya aprobado la Evaluación de la Conformidad o, en caso de que el personal haya ingresado a la plantilla del Regulado con fecha posterior a la última Evaluación de la Conformidad, que cuente con el expediente individual del Operador conforme a lo establecido en el numeral 7.1.3.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.7 · Dictamen de operación y mantenimiento","seccion_nombre":"7.7.4"},{"id":"bb6e0b1e-d5de-5a31-9d9e-f1d6fa5b4454","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":110,"identificador":"Numeral 7.7.5","contenido":"<div>7.7.5. La vigencia del dictamen de operación y mantenimiento será de 1 año a partir de la fecha de emisión.</div>","tipo_articulo":"ordinario","titulo_nombre":"Operación y mantenimiento","capitulo_nombre":"7.7 · Dictamen de operación y mantenimiento","seccion_nombre":"7.7.5"},{"id":"836d5394-4441-513c-be31-0ee88596a1b0","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":111,"identificador":"Numeral 8. Término de operación","contenido":"<div>8. Término de operación</div>\n<div>Para dar de baja una Unidad de Transporte de su parque vehicular, el Regulado debe cumplir con lo siguiente:</div>","tipo_articulo":"ordinario","titulo_nombre":"Término de operación","capitulo_nombre":null,"seccion_nombre":null},{"id":"2ccdf383-92b4-55f9-a468-bb66c3fc47dd","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":112,"identificador":"Numeral 8.1","contenido":"<div>8.1. Cuando el Recipiente No Desmontable del Auto-tanque o Semirremolque no cumple con las condiciones de integridad establecidas en la presente Norma Oficial Mexicana de Emergencia para continuar en uso realizando la actividad de Transporte de GLP, se deben realizar las siguientes acciones:</div>\n<div>a) Retirar, borrar o cubrir de forma segura e irreversible la placa de especificaciones del Recipiente No Desmontable;</div>\n<div>b) El Recipiente No Desmontable, sus accesorios, dispositivos de seguridad, mangueras, tuberías y conexiones deben quedar libres de cualquier sustancia inflamable, agua o sedimento que le confiera alguna característica de peligrosidad;</div>\n<div>c) Ejecutar el procedimiento de limpieza, inertización y monitoreo de explosividad, de acuerdo con lo establecido en el numeral 7.3.1.1, inciso e), o contar con el documento que acredite que la limpieza y control de remanentes se realizó de conformidad con la NOM-019-SCT2/2015;</div>\n<div>d) El Recipiente No Desmontable debe presentar un nivel de inflamabilidad o explosividad de 0 %, comprobado por medio de un explosímetro o detector de mezcla explosiva;</div>\n<div>e) Elaborar un reporte de término de operación que incluya la información siguiente:</div>\n<div>1. Identificación de la Unidad de Transporte, mediante el número de permiso otorgado por la autoridad competente en materia del Sector Hidrocarburos y número económico;</div>\n<div>2. Número de serie del Recipiente No Desmontable;</div>\n<div>3. Registro de las condiciones por las cuáles el Recipiente No Desmontable fue retirado de operación;</div>\n<div>4. Fecha de término de operación;</div>\n<div>5. Fecha y registro de las actividades de purga, limpieza e inertización;</div>\n<div>6. Fecha y registro del personal capacitado, o en su caso de la persona física o moral que realiza la limpieza del Recipiente No Desmontable;</div>\n<div>7. El documento que acredite la limpieza del Recipiente No Desmontable, cuando esta se ejecute por un prestador de servicios que cuente con registro como generador de residuos y/o como Centro de Limpieza de autotransporte federal;</div>\n<div>8. Estimación de los residuos generados y su clasificación;</div>\n<div>9. En su caso, registro de los prestadores de servicios autorizados para la gestión de los residuos generados, y</div>\n<div>10. El manifiesto de entrega, transporte y recepción de los residuos generados, para acreditar el destino final del Recipiente No desmontable, así como de los residuos generados por su limpieza y disposición.</div>","tipo_articulo":"ordinario","titulo_nombre":"Término de operación","capitulo_nombre":"8 · Término de operación","seccion_nombre":"8.1"},{"id":"99ff4624-f95c-5911-a90a-70ca5e5d8296","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":113,"identificador":"Numeral 8.2","contenido":"<div>8.2. Cuando la Unidad de Transporte sea dada de baja por fines comerciales, logísticos o de renovación de parque vehicular, pero conserva las condiciones de integridad para el Transporte de GLP establecidas en la presente Norma Oficial Mexicana de Emergencia, el Regulado debe:</div>\n<div>a) Elaborar un reporte de término de operación que incluya la información siguiente:</div>\n<div>1. Identificación de la Unidad de Transporte, mediante el número de permiso otorgado por la autoridad competente en materia del Sector Hidrocarburos y número económico;</div>\n<div>2. Número de serie del Recipiente No Desmontable;</div>\n<div>3. Registro de las condiciones por las cuáles la Unidad de Transporte fue retirada de operación;</div>\n<div>4. Fecha de término de operación, y</div>\n<div>5. Registro de los últimos resultados de las pruebas establecidas en la presente Norma Oficial Mexicana de Emergencia.</div>\n<div>b) Conservar el Expediente de integridad de la Unidad de Transporte durante el tiempo que se encuentre bajo su resguardo.</div>","tipo_articulo":"ordinario","titulo_nombre":"Término de operación","capitulo_nombre":"8 · Término de operación","seccion_nombre":"8.2"},{"id":"016560ee-7db0-504e-a7c8-e83292c25c6c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":114,"identificador":"Numeral 8.3","contenido":"<div>8.3. El Regulado debe conservar el reporte de término de operación por un periodo de 5 años posteriores a la fecha de término de operación para cuando la Agencia lo requiera.</div>","tipo_articulo":"ordinario","titulo_nombre":"Término de operación","capitulo_nombre":"8 · Término de operación","seccion_nombre":"8.3"},{"id":"d30fb73a-b816-572e-9157-8835b045917c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":115,"identificador":"Numeral 9. Procedimiento de Evaluación de la Conformidad","contenido":"<div>9. Procedimiento de Evaluación de la Conformidad</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":null,"seccion_nombre":null},{"id":"1ab9ff54-0306-5303-b311-ea2481e0e5b4","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":116,"identificador":"Numeral 9.1","contenido":"<div>9.1. Consideraciones generales</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9 · Procedimiento de Evaluación de la Conformidad","seccion_nombre":"9.1"},{"id":"2e233b86-02a4-5e5d-9131-d3c9c96de94d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":117,"identificador":"Numeral 9.1.1","contenido":"<div>9.1.1. El objetivo del presente Procedimiento de Evaluación de la Conformidad (PEC) es establecer las directrices y criterios para comprobar que el Regulado cumple con las especificaciones técnicas y requisitos establecidos en la presente Norma Oficial Mexicana de Emergencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.1 · Consideraciones generales","seccion_nombre":"9.1.1"},{"id":"df9e5bb0-9b34-5b71-a2d1-61dcdf7362d7","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":118,"identificador":"Numeral 9.1.2","contenido":"<div>9.1.2. El PEC se llevará a cabo por medio de examen de documentos y constatación ocular, según corresponda, por una unidad de inspección acreditada por una Entidad de Acreditación y aprobada por la Agencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.1 · Consideraciones generales","seccion_nombre":"9.1.2"},{"id":"89900bd8-b8b3-57d5-bf14-fad1d20d9a63","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":119,"identificador":"Numeral 9.1.3","contenido":"<div>9.1.3. La unidad de inspección debe realizar la Evaluación de la Conformidad de manera presencial en la Instalación del Regulado.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.1 · Consideraciones generales","seccion_nombre":"9.1.3"},{"id":"24963cd9-9694-5ad6-a490-c7014007f084","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":120,"identificador":"Numeral 9.1.4","contenido":"<div>9.1.4. Las visitas para la Evaluación de la Conformidad deben documentarse en un acta que contenga como mínimo, lo siguiente:</div>\n<div>a) Nombre, número de acreditación, número de aprobación y domicilio de la unidad de inspección;</div>\n<div>b) Nombre, denominación o razón social del Regulado;</div>\n<div>c) Número de permiso emitido por la autoridad competente en materia del Sector Hidrocarburos;</div>\n<div>d) Domicilio de la Instalación del Regulado donde se realiza la Evaluación de la Conformidad;</div>\n<div>e) Identificación de la o las Unidades de Transporte sometidas a Evaluación de la Conformidad;</div>\n<div>f) Listado del total de operadores del Regulado que realizan la actividad de Transporte de GLP, que incluya como mínimo nombre (s), apellidos y numero de empleado;</div>\n<div>g) Fecha y hora de inicio y termino en que se realiza la o las visitas;</div>\n<div>h) Nombre y firma autógrafa del personal profesional técnico especializado que realiza la inspección;</div>\n<div>i) Nombre y firma autógrafa del personal del Regulado que atiende la inspección;</div>\n<div>j) Nombre y firma autógrafa del testigo o testigos de asistencia;</div>\n<div>k) Tipo de inspección (examen de documentos y/o constatación ocular);</div>\n<div>l) Descripción de los documentos examinados durante la inspección, y</div>\n<div>m) Resultado de la Evaluación de la conformidad.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.1 · Consideraciones generales","seccion_nombre":"9.1.4"},{"id":"e0708bd7-9813-5ecd-9ac4-0ca269e4d8af","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":121,"identificador":"Numeral 9.2","contenido":"<div>9.2. Del inicio de operación</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9 · Procedimiento de Evaluación de la Conformidad","seccion_nombre":"9.2"},{"id":"b7d05ebd-3f12-5913-911f-57f26a991942","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":122,"identificador":"Numeral 9.2.1","contenido":"<div>9.2.1. Generalidades</div>\n<div>El PEC para el inicio de operación se debe realizar para cada Unidad de Transporte del Regulado.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.2 · Del inicio de operación","seccion_nombre":"9.2.1"},{"id":"6f7acf95-daae-597e-9e60-365eeacac27a","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":123,"identificador":"Numeral 9.2.2","contenido":"<div>9.2.2. Examen de documentos</div>\n<div>La unidad de inspección debe examinar el Expediente de integridad de la Unidad de Transporte tomando en cuenta los criterios siguientes:</div>\n<div>a) Comprobar que los documentos que integran el Expediente de integridad según lo establecido en la presente Norma Oficial Mexicana de Emergencia correspondan con la Unidad de Transporte objeto de la Evaluación de la Conformidad, por medio de la información de identificación de la Unidad de Transporte, número de serie del Recipiente No Desmontable y datos de identificación de válvulas y accesorios.</div>\n<div>b) Evaluar en el Expediente de integridad el cumplimiento de los numerales 6.1.2, 6.1.6, 6.1.7, 6.2.1 (inciso j) y numerales 1 a 3 del inciso l)), 6.2.2, 6.2.3, 6.2.4, 6.2.5, 6.2.6 (cuando aplique), 6.2.7, 6.2.8 (únicamente cuando la realice un laboratorio de ensayos acreditado por una Entidad de Acreditación o, en su caso, por una persona certificada prueba de hermeticidad, nivel 2 conforme a la NMX-B-482-CANACERO-2016 o estándar internacional o extranjero equivalente) y 6.3 de la presente Norma Oficial Mexicana de Emergencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.2 · Del inicio de operación","seccion_nombre":"9.2.2"},{"id":"c15b7a78-46b6-5418-ad67-54f276aa3026","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":124,"identificador":"Numeral 9.2.3","contenido":"<div>9.2.3. Constatación ocular</div>\n<div>La unidad de inspección debe evaluar visualmente las condiciones de la Unidad de Transporte para comprobar que cumple con los numerales 6.1.1, 6.1.3, 6.1.4, 6.1.5, 6.2.1 (excepto inciso j) y numerales 1 a 3 del inciso l)) y 6.2.5 de la presente Norma Oficial Mexicana de Emergencia previo a iniciar operaciones.</div>\n<div>Particularmente en el caso del numeral 6.1.4, además de la revisión visual de las señales y avisos, se debe realizar la medición de los caracteres y del cartel de identificación.</div>\n<div>Para el caso del numeral 6.2.1 inciso i), además de la existencia de la entrada pasa-hombre, se debe realizar la medición de su diámetro.</div>\n<div>En el caso de que la prueba de hermeticidad referida en el numeral 6.2.8 la realice personal competente del Regulado, esta podrá realizarse durante el Procedimiento de Evaluación de la Conformidad y ser validada por la unidad de inspección acreditada por la Entidad de Acreditación y aprobada por la Agencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.2 · Del inicio de operación","seccion_nombre":"9.2.3"},{"id":"959f0f82-11aa-50fe-a260-462bd12c9299","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":125,"identificador":"Numeral 9.3","contenido":"<div>9.3. De la operación y mantenimiento</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9 · Procedimiento de Evaluación de la Conformidad","seccion_nombre":"9.3"},{"id":"db9ed123-6f57-5bf9-a3b1-b68c75950a7c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":126,"identificador":"Numeral 9.3.1","contenido":"<div>9.3.1. Generalidades</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3 · De la operación y mantenimiento","seccion_nombre":"9.3.1"},{"id":"18abe534-f244-58e9-b7d2-9d8a7f056634","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":127,"identificador":"Numeral 9.3.1.1","contenido":"<div>9.3.1.1. El PEC en la etapa de operación y mantenimiento se debe realizar para cada Unidad de Transporte y para el total de Operadores del Regulado que realizan la actividad de Transporte de GLP.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3.1 · Generalidades","seccion_nombre":"9.3.1.1"},{"id":"342fcdfc-d62f-54ed-9f3f-6b122a203324","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":128,"identificador":"Numeral 9.3.1.2","contenido":"<div>9.3.1.2. El Regulado debe proporcionar a la unidad de inspección un listado de las Unidades de Transporte que someterá a evaluación, así como la relación del total de operadores del Regulado que realizan la actividad de Transporte de GLP.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3.1 · Generalidades","seccion_nombre":"9.3.1.2"},{"id":"da920b3a-7dc5-5133-8697-78f3a4746d78","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":129,"identificador":"Numeral 9.3.2","contenido":"<div>9.3.2. Examen de documentos</div>\n<div>El Regulado debe proporcionar a la unidad de inspección los siguientes documentos:</div>\n<div>a) Programa anual y trienal de capacitación</div>\n<div>1. La unidad de inspección debe constatar el numeral 7.1.1, así como que los operadores de Auto-tanques indicados en el listado al que se refiere el numeral 9.3.1.2 estén incluidos en el programa anual de capacitación y que la capacitación programada a la fecha de la Evaluación de la Conformidad se haya cumplido, basado en los registros de capacitación vigentes.</div>\n<div>2. La unidad de inspección debe constatar el numeral 7.1.3, así como que los operadores de Semirremolques indicados en el listado al que se refiere el numeral 9.3.1.2 estén incluidos en el programa trienal de capacitación y que la capacitación programada a la fecha de la Evaluación de la Conformidad se haya cumplido, basado en los registros de capacitación vigentes.</div>\n<div>b) Expediente individual de los operadores</div>\n<div>1. La unidad de inspección debe examinar el expediente individual de los operadores incluidos en el listado al que se refiere el numeral 9.3.1.2, para constatar que cada expediente cuente con los documentos referidos en el numeral 7.1.6.</div>\n<div>2. La unidad de inspección debe examinar que las constancias oficiales de competencias o habilidades laborales (DC3) a las que se refiere el numeral 7.1.6, inciso b), indiquen el nombre del operador, las fechas de capacitación, el nombre del Agente capacitador externo y que dichas constancias no excedan de un año a partir de su emisión para operadores de Auto-tanques, y de tres años a partir de su emisión para operadores de Semirremolques.</div>\n<div>3. La unidad de inspección debe examinar que los planes de capacitación o documentos expedidos por el Agente capacitador externo contienen los temas que fueron impartidos en la capacitación, a través de los cuales se obtuvieron las constancias oficiales de competencias o habilidades laborales (DC3) y estos temas corresponden a los establecidos en los numerales 7.1.1 y 7.1.3, según corresponda.</div>\n<div>4. La unidad de inspección debe examinar que el certificado de competencia laboral vigente en el Estándar de Competencia EC1731 Operación del tractocamión de quinta rueda y semirremolque para Transporte de Gas L.P., emitido por el CONOCER, incluya el nombre completo del Operador, fecha de expedición y folio.</div>\n<div>5. Las constancias oficiales de competencias o habilidades laborales (DC3) expedidas por Agentes capacitadores externos a que refiere el numeral 7.1.4 deben incluir el número de autorización y registro ante la STPS.</div>\n<div>c) Manual, procedimientos y bitácora de operación.</div>\n<div>La unidad de inspección debe constatar que existan manuales, procedimientos y bitácoras de operación disponibles para el operador, y que estos se cumplen con lo establecido en el numeral 7.3 y 7.5.1.</div>\n<div>d) Programa y bitácora de mantenimiento, inspecciones y pruebas de la Unidad de Transporte.</div>\n<div>La unidad de inspección debe constatar que exista un programa de mantenimiento, inspecciones y pruebas y que este tenga congruencia con los registros en bitácora de las actividades de mantenimiento, los resultados de las pruebas realizadas y, en su caso, los dictámenes obtenidos; así como comprobar el cumplimiento de los numerales 7.3.2, 7.3.3, 7.4.3, 7.4.5.16 y 7.5.1.</div>\n<div>La unidad de inspección debe identificar si se registró en bitácora alguno de los escenarios indicados en los numerales 7.4.5.6, 7.4.5.7, 7.4.5.8, 7.4.5.9, 7.4.5.10, 7.4.5.11 y 7.4.5.14, de ser así, debe constatar que se hayan realizado las acciones referidas en dichos numerales y, en su caso, se hayan cumplido los numerales 7.4.5.12, 7.4.5.13 y 7.4.5.15.</div>\n<div>La unidad de inspección debe constatar que los documentos que avalan el cumplimiento de los numerales referidos en el párrafo anterior, correspondan con el Auto-tanque o Semirremolque objeto de la Evaluación de la Conformidad, por medio de la información de identificación de la Unidad de Transporte, número de serie del Recipiente No Desmontable y datos de identificación de válvulas y accesorios.</div>\n<div>e) Informes de resultados de inspección y/o pruebas.</div>\n<div>La unidad de inspección debe constatar el cumplimiento del numeral 7.4, considerando lo siguiente:</div>\n<div>1. Si se realizó la inspección visual interna, pruebas o reparaciones al interior del Recipiente No Desmontable, se debe verificar el cumplimiento del numeral 7.4.2 mediante el registro en bitácora y documento que acredite la limpieza y control de remanentes.</div>\n<div>2. Las inspecciones y pruebas se realizaron con la periodicidad establecida en el numeral 7.4.4 y conforme a lo establecido en el numeral 7.4.5 según la inspección o prueba que corresponda.</div>\n<div>3. Para cada prueba o inspección periódica referida en el numeral 7.4.4 o en caso de reparaciones con soldadura o exposición al fuego, los informes de resultados deben contener los datos establecidos en el numeral 7.4.5.17.</div>\n<div>4. La unidad de inspección debe constatar que los informes de resultados correspondan con la Unidad de Transporte sometida a evaluación por medio de los datos de identificación de la Unidad, número de serie o marcado del Recipiente No Desmontable, válvulas o accesorios.</div>\n<div>5. El personal que realiza la inspección visual, mantenimiento y pruebas cuenta con constancias de capacitación o certificación, según lo solicite el requisito, que avale su competencia, y este personal corresponde al registrado en la bitácora correspondiente a la inspección visual, mantenimiento o pruebas realizada.</div>\n<div>f) Expediente de integridad de la Unidad de Transporte.</div>\n<div>La unidad de inspección debe constatar el cumplimiento de los numerales 7.4.5.15, 7.5.2 y 7.5.3, asi como el numeral 7.5.4 para Auto-tanque y comprobar que los documentos que integran el Expediente de integridad, según lo establecido en la presente Norma Oficial Mexicana de Emergencia, correspondan con el Auto-tanque o Semirremolque objeto de la Evaluación de la Conformidad, por medio de los datos de identificación de la Unidad, número de serie del Recipiente No Desmontable y datos de identificación de válvulas, mangueras y accesorios, cuando aplique.</div>\n<div>g) Documentos a bordo de la unidad</div>\n<div>La unidad de inspección debe constatar el cumplimiento de los numerales 7.2 y 7.3.1.4 de la Norma Oficial Mexicana de Emergencia.</div>\n<div>h) Gobernador de velocidad</div>\n<div>La unidad de inspección debe constatar el cumplimiento del numeral 7.5.4 para los Tractocamiones que formen parte de su parque vehicular.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3 · De la operación y mantenimiento","seccion_nombre":"9.3.2"},{"id":"7d74afe8-44fa-5713-a62e-81efe655a6fa","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":130,"identificador":"Numeral 9.3.3","contenido":"<div>9.3.3. Constatación ocular</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3 · De la operación y mantenimiento","seccion_nombre":"9.3.3"},{"id":"5dd460c9-f335-5eff-82b5-5a163f5e9c3b","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":131,"identificador":"Numeral 9.3.3.1","contenido":"<div>9.3.3.1. La unidad de inspección debe evaluar visualmente en el Auto-tanque o Semirremolque el cumplimiento de los numerales 7.2, 7.3.1.4 y 7.4.5.1 de la presente Norma Oficial Mexicana de Emergencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3.3 · Constatación ocular","seccion_nombre":"9.3.3.1"},{"id":"96ea8f91-59ab-5429-bccf-8767a301af68","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":132,"identificador":"Numeral 9.3.3.2","contenido":"<div>9.3.3.2. En el caso de que la prueba de hermeticidad referida en el numeral 7.4.5.2 la realice personal competente del Regulado, esta podrá realizarse durante el Procedimiento de Evaluación de la Conformidad y ser validada por la unidad de inspección acreditada por la Entidad de Acreditación y aprobada por la Agencia.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.3.3 · Constatación ocular","seccion_nombre":"9.3.3.2"},{"id":"53ca1844-505c-504d-a1bc-e2ada8961d13","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":133,"identificador":"Numeral 9.4","contenido":"<div>9.4. Del resultado de la Evaluación de la Conformidad</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9 · Procedimiento de Evaluación de la Conformidad","seccion_nombre":"9.4"},{"id":"3fdba69f-bf9a-50b3-89cf-b031e310b128","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":134,"identificador":"Numeral 9.4.1","contenido":"<div>9.4.1. El resultado de la Evaluación de la Conformidad debe documentarse en una lista de inspección, de formato libre, que contenga como mínimo, lo siguiente:</div>\n<div>a) Tipo de Unidad de Transporte (Auto-tanque o Tractocamión-Semirremolque), número de placas, datos de identificación de la o las Unidades de Transporte sometidas a Evaluación de la Conformidad;</div>\n<div>b) Listado del total de operadores del Regulado que realizan la actividad de Transporte de GLP.; indicando para cada operador nombre completo y numero de empleado;</div>\n<div>c) Número de serie del Recipiente No Desmontable, capacidad en litros, nombre del fabricante y fecha de fabricación de cada Unidad de Transporte evaluada;</div>\n<div>d) Lista de elementos inspeccionados documentales y físicos;</div>\n<div>e) Tipo de inspección (examen de documentos y/o constatación ocular) y resultado del cumplimiento para cada requisito normativo, para cada Unidad de Transporte sometida a Evaluación de la Conformidad y para cada operador del listado referido en el inciso b) del numeral 9.4.1;</div>\n<div>f) Evidencia que soporte el cumplimiento del requisito y su descripción, cuando aplique;</div>\n<div>g) En el caso de dictámenes e informes de resultados de pruebas e inspecciones, registrar la fecha de la prueba o inspección, el nombre o razón social de la persona física o moral que las realizó, el folio o número identificador del informe, el número de acreditación del laboratorio, unidad de inspección o certificación de competencias de la persona que ejecuta las pruebas e inspecciones, y</div>\n<div>h) No conformidades y observaciones indicando la resolución de estas.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.4 · Del resultado de la Evaluación de la Conformidad","seccion_nombre":"9.4.1"},{"id":"c615aaee-e17b-5be1-84e0-feb6883c3e19","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":135,"identificador":"Numeral 9.4.2","contenido":"<div>9.4.2. La unidad de inspección debe emitir, para cada Unidad de Transporte, el dictamen de inicio de operación o el dictamen de operación y mantenimiento, según sea el caso, cuando se compruebe el cumplimiento de los requisitos y especificaciones establecidos en el capítulo 6. Inicio de operación o el capítulo 7. Operación y mantenimiento, según corresponda, de la presente Norma Oficial Mexicana de Emergencia. El dictamen debe indicar los datos de identificación de las Unidades de Transporte, así como un número de folio o de identificación irrepetible. No se deben emitir Dictámenes de Operación y Mantenimiento para Unidades de Transporte, si la totalidad de Operadores no han cumplido con los requisitos establecidos en la presente Norma Oficial Mexicana de Emergencia.</div>\n<div>Las Unidades de Transporte y los operadores que no aprobaron la Evaluación de la Conformidad, no podrán realizar la actividad de Transporte de GLP.</div>","tipo_articulo":"ordinario","titulo_nombre":"Procedimiento de Evaluación de la Conformidad","capitulo_nombre":"9.4 · Del resultado de la Evaluación de la Conformidad","seccion_nombre":"9.4.2"},{"id":"b52c5c20-9c8e-5639-b288-768c97ada6f3","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":136,"identificador":"Numeral 10. Grado de concordancia con normas internacionales","contenido":"<div>10. Grado de concordancia con normas internacionales</div>\n<div>La presente Norma Oficial Mexicana de Emergencia no es equivalente (NEQ) con ninguna Norma Internacional, por no existir esta última al momento de su elaboración.</div>","tipo_articulo":"ordinario","titulo_nombre":"Grado de concordancia con normas internacionales","capitulo_nombre":null,"seccion_nombre":null},{"id":"eb94fb69-f363-5a49-abbc-5cb6b81f0388","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":137,"identificador":"Numeral 11. Verificación de la Norma Oficial Mexicana de Emergencia","contenido":"<div>11. Verificación de la Norma Oficial Mexicana de Emergencia</div>\n<div>La Verificación del cumplimiento de la presente Norma Oficial Mexicana de Emergencia corresponde a la Agencia y, se llevará a cabo de la siguiente manera:</div>\n<div>a) En coordinación con las autoridades federales, estatales y locales competentes en materia de tránsito, movilidad, protección civil y del orden público, para que, dentro del ámbito de sus competencias, verifiquen y supervisen el cumplimiento de la presente Norma Oficial Mexicana de Emergencia, y</div>\n<div>b) En coordinación con las autoridades de los gobiernos de los Estados y de la Ciudad de México, de los municipios y de las Alcaldías, con la finalidad de establecer acciones que faciliten la verificación de la presente Norma Oficial Mexicana de Emergencia.</div>\n<div>El incumplimiento con lo dispuesto en la presente Norma Oficial Mexicana de Emergencia será sancionado por la Agencia, en términos de la Ley de Infraestructura de la Calidad y demás disposiciones aplicables.</div>","tipo_articulo":"ordinario","titulo_nombre":"Verificación de la Norma Oficial Mexicana de Emergencia","capitulo_nombre":null,"seccion_nombre":null},{"id":"a5ec6cc7-eeba-533a-8f78-1f7afd3b95ed","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":138,"identificador":"Apéndice A","contenido":"<div>(Normativo)</div>\n<div>Listado de revisión visual diaria</div>\n<div>Antes de la puesta en marcha de la Unidad de Transporte se debe realizar la revisión visual diaria, según la Unidad que corresponda, conforme a lo establecido en este Apéndice.</div>\n<div>Los conceptos de este Apéndice pueden conformar un documento independiente, formar parte de los procedimientos de operación o de la bitácora de revisión ocular de la NOM-006-SCT-2-2023.</div>","tipo_articulo":"anexo","titulo_nombre":"Apéndice A","capitulo_nombre":null,"seccion_nombre":null},{"id":"ee83174b-18d7-5ea6-87e6-fbc0bf43617c","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":139,"identificador":"Apéndice A · A.1","contenido":"<div>A.1. Auto-tanque</div>\n<table><tbody><tr><td>FECHA: ___/___/____</td><td>FIRMA(S)</td></tr><tr><td>NOMBRE DEL OPERADOR: _________________________________________________</td><td></td><td></td></tr><tr><td>_________________________________________________________________________ _________________________________________________________________________ _________________________________________________________________________</td><td></td><td></td></tr><tr><td>IDENTIFICACIÓN DE LA UNIDAD: ____________________________________________</td><td>______________</td></tr></tbody></table>\n<table><tbody><tr><td>Componentes</td><td>Criterio de aceptación</td><td>Cumple</td><td>No cumple</td></tr><tr><td>RECIPIENTE, VÁLVULAS, ACCESORIOS</td><td></td><td></td></tr><tr><td>Recipiente No Desmontable</td><td>Libre de abolladuras, protuberancias, incisiones o cavidades</td><td></td><td></td></tr><tr><td>Chasis</td><td>Sin fisuras</td><td></td><td></td></tr><tr><td>Coples</td><td>Sin fuga</td><td></td><td></td></tr><tr><td>Válvulas y accesorios</td><td>Sin fuga</td><td></td><td></td></tr><tr><td>Indicador de presión, temperatura y nivel</td><td>Sin fuga y funciona</td><td></td><td></td></tr><tr><td>El nivel de llenado del Recipiente no excede el 90 %</td><td></td><td></td></tr><tr><td>Manguera, en caso de contar con ella</td><td>Sin protuberancias</td><td></td><td></td></tr><tr><td>Sin cortes o raspaduras</td><td></td><td></td></tr><tr><td>Recubrimiento de hule</td><td></td><td></td></tr><tr><td>Sin daño o deformación en malla interna</td><td></td><td></td></tr><tr><td>Tornillería completa</td><td></td><td></td></tr><tr><td>Sin desgaste o daño al recubrimiento o accesorios</td><td></td><td></td></tr><tr><td>Válvula de recepción</td><td>Sin daños y sin fugas</td><td></td><td></td></tr><tr><td>INTERIOR (CABINA)</td><td></td><td></td></tr><tr><td>Documentos: a) Licencia federal tipo &quot;E&quot; vigente; b) Copia del permiso y autorización de inicio de operaciones de la Unidad de Transporte vigente expedido por la autoridad competente en materia del Sector Hidrocarburos; c) Tarjeta de circulación vigente; d) Hoja de Emergencia para el Transporte de Substancias, Materiales y Residuos Peligrosos, específica para GLP, o Guía de respuesta en caso de emergencia; e) Copia de la póliza del seguro vigente con las coberturas establecidas en la regulación aplicable, y f) Copia del dictamen vigente de esta Norma Oficial Mexicana de Emergencia o de la Norma Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025, según aplique.</td><td>A bordo</td><td></td><td></td></tr><tr><td>Indicadores de presión de aire/vacío</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Dispositivo de advertencia de poco aire o vacío</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Luces direccionales e indicadores de tablero</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Volante</td><td>Dirección sin juego excesivo</td><td></td><td></td></tr><tr><td>Calentador-Desempañador</td><td>Funciona</td><td></td><td></td></tr><tr><td>Cinturón de seguridad</td><td>En buen estado y funciona</td><td></td><td></td></tr><tr><td>Parabrisas</td><td>Sin daño</td><td></td><td></td></tr><tr><td>Limpiadores</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Espejos retrovisores</td><td>Sin daño</td><td></td><td></td></tr><tr><td>Sistema de frenos (De estacionamiento y de circulación/servicio)</td><td>Funciona</td><td></td><td></td></tr><tr><td>FRENTE EXTERIOR</td><td></td><td></td></tr><tr><td>Defensa</td><td>Sujeción correcta, sin daños</td><td></td><td></td></tr><tr><td>Sistema de luces (Faros principales, gálibo, direccionales)</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Escape</td><td>Sujeto, sin daño, e incluye matachispas</td><td></td><td></td></tr><tr><td>LADO IZQUIERDO Y LADO DERECHO</td><td></td><td></td></tr><tr><td>Tanque de combustible</td><td>Sin fugas</td><td></td><td></td></tr><tr><td>Tapón del tanque de combustible (gasolina o diésel)</td><td>Cierre hermético</td><td></td><td></td></tr><tr><td>Sistema de luces (Marcha atrás, laterales)</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Llanta de refacción</td><td>Presión conforme a la recomendación de fabricante y sin daños</td><td></td><td></td></tr><tr><td>Llantas</td><td>Presión conforme a la recomendación de fabricante y sin daños (bulto, protuberancia o nudo observable)</td><td></td><td></td></tr><tr><td>Dibujo homogéneo</td><td></td><td></td></tr><tr><td>Rines</td><td>Sin daños (grieta en rayos o grieta en cordones de soldadura)</td><td></td><td></td></tr><tr><td>Birlos y tuercas</td><td>Completos y sin daños (flojos, faltantes, rotos, agrietados, estropeados, etc.)</td><td></td><td></td></tr><tr><td>Guardafangos (Loderas)</td><td>Completos y sin daños</td><td></td><td></td></tr><tr><td>PARTE POSTERIOR DE LA UNIDAD</td><td></td><td></td></tr><tr><td>Sistema de luces (Direccionales, Intermitentes, de advertencia, de frenado)</td><td>Funcionando</td><td></td><td></td></tr><tr><td>Defensa</td><td>Que exista, sujeción correcta y sin daños</td><td></td><td></td></tr><tr><td>PARTE INFERIOR</td><td></td><td></td></tr><tr><td>Cinta estática</td><td>Que toque el piso</td><td></td><td></td></tr><tr><td>EQUIPO DE EMERGENCIA</td><td></td><td></td></tr><tr><td>Extintor, con capacidad de 9 kg, para fuego tipo A, B, C.</td><td>Sujeto y con fecha de inspección y recarga vigente</td><td></td><td></td></tr><tr><td>Señales reflejantes de seguridad</td><td>A bordo</td><td></td><td></td></tr><tr><td>Calzas</td><td>A bordo</td><td></td><td></td></tr><tr><td>LETREROS, SEÑALES Y AVISOS</td><td></td><td></td></tr><tr><td>Letreros, señales y avisos</td><td>Claros, legibles, sin deformaciones o decoloraciones y no obstruidos</td><td></td><td></td></tr></tbody></table>\n<table><tbody><tr><td>ESTA SECCIÓN SE UTILIZA EN CASO DE DETECTAR INCUMPLIMIENTOS EN LA REVISIÓN</td></tr><tr><td>Defectos o anomalías observadas:</td><td>Fecha de la acción correctiva:</td></tr><tr><td></td><td></td></tr><tr><td></td><td></td></tr><tr><td></td><td></td></tr><tr><td>Nombre del responsable de la corrección/reparación:</td><td>Firma del responsable:</td></tr></tbody></table>","tipo_articulo":"anexo","titulo_nombre":"Apéndice A (Normativo)","capitulo_nombre":"Apéndice A (Normativo)","seccion_nombre":"A.1"},{"id":"6385ca78-bded-5448-b5f4-7e10b961a899","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":140,"identificador":"Apéndice A · A.2","contenido":"<div>A.2. Tractocamión-Semirremolque</div>\n<table><tbody><tr><td>FECHA: ___/___/____</td><td></td><td>FIRMA</td></tr><tr><td>NOMBRE DEL OPERADOR: ________________________________________________</td><td></td><td></td></tr><tr><td>IDENTIFICACIÓN DE LA UNIDAD:</td><td>______________________________</td><td>_____________</td></tr><tr><td>Componentes</td><td>Criterio de aceptación</td><td>Cumple</td><td>No cumple</td></tr><tr><td>INTERIOR (TRACTOCAMIÓN)</td><td></td><td></td></tr><tr><td>Documentos: a) Licencia federal tipo &quot;E&quot; vigente; b) Copia del permiso y autorización de inicio de operaciones de la Unidad de Transporte vigente expedido por la autoridad competente en materia del Sector Hidrocarburos; c) Tarjeta de circulación vigente; d) Hoja de Emergencia para el Transporte de Substancias, Materiales y Residuos Peligrosos, específica para GLP, o Guía de respuesta en caso de emergencia; e) Copia de la póliza del seguro vigente con las coberturas establecidas en la regulación aplicable, y f) Copia del dictamen vigente de esta Norma Oficial Mexicana de Emergencia o de la Norma Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025, según aplique.</td><td>A bordo</td><td></td><td></td></tr><tr><td>Indicadores de presión de aire/vacío</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Dispositivo de advertencia de poco aire o vacío</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Luces direccionales e indicadores de tablero</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Volante</td><td>Dirección sin juego excesivo</td><td></td><td></td></tr><tr><td>Calentador-Desempañador</td><td>Funciona</td><td></td><td></td></tr><tr><td>Indicadores del tablero</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Cinturón de seguridad</td><td>En buen estado y funciona</td><td></td><td></td></tr><tr><td>Parabrisas</td><td>Sin daño</td><td></td><td></td></tr><tr><td>Limpiadores</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Espejos retrovisores</td><td>Sin daño</td><td></td><td></td></tr><tr><td>Sistema de frenos (De estacionamiento y de circulación/servicio)</td><td>Funciona</td><td></td><td></td></tr><tr><td>FRENTE EXTERIOR (TRACTOCAMIÓN)</td><td></td><td></td></tr><tr><td>Defensa</td><td>Sujeción correcta, sin daños</td><td></td><td></td></tr><tr><td>Sistema de luces (Faros principales, gálibo, direccionales)</td><td>Completas y funcionando</td><td></td><td></td></tr><tr><td>Escape</td><td>Sujeto, sin daño, e incluye matachispas</td><td></td><td></td></tr><tr><td>LADO IZQUIERO Y DERECHO (TRACTOCAMIÓN-SEMIRREMOLQUE)</td><td></td><td></td></tr><tr><td>Tapón del tanque de combustible</td><td>Cierre hermético</td><td></td><td></td></tr><tr><td>Sistema de luces (Direccionales, Intermitentes, de advertencia, de frenado)</td><td>Completas y funcionando</td><td></td><td></td></tr><tr><td>Cintas reflejantes</td><td>Completas y visibles</td><td></td><td></td></tr><tr><td>Llantas</td><td>Presión conforme a la recomendación de fabricante y sin daños (bulto, protuberancia o nudo observable)</td><td></td><td></td></tr><tr><td>Dibujo homogéneo</td><td></td><td></td></tr><tr><td>Rines</td><td>Sin daños (grieta en rayos o grieta en cordones de soldadura)</td><td></td><td></td></tr><tr><td>Birlos y tuercas</td><td>Completos y en buen estado</td><td></td><td></td></tr><tr><td>Guardafangos (Loderas)</td><td>Completos, sin daños</td><td></td><td></td></tr><tr><td>PARTE POSTERIOR (TRACTOCAMIÓN)</td><td></td><td></td></tr><tr><td>Sistema de luces</td><td>Completas y funcionando</td><td></td><td></td></tr><tr><td>Escape</td><td>Bien sujetado, sin daños e incluye matachispas</td><td></td><td></td></tr><tr><td>Conexión quinta rueda</td><td>Sin daños (deformaciones, golpes, pandeo)</td><td></td><td></td></tr><tr><td>Enganche con el Semirremolque de acuerdo con el procedimiento referido en el 7.3.1.1 inciso c)</td><td></td><td></td></tr><tr><td>Con lubricación</td><td></td><td></td></tr><tr><td>Tornillería completa</td><td></td><td></td></tr><tr><td>Libre de obstrucciones</td><td></td><td></td></tr><tr><td>Herrajes de sujeción completos y sin juego</td><td></td><td></td></tr><tr><td>EQUIPO DE EMERGENCIA</td><td></td><td></td></tr><tr><td>Extintor, con capacidad de 9 kg, para fuego tipo A, B, C.</td><td>Sujeto al Semirremolque, fecha de inspección y recarga vigente</td><td></td><td></td></tr><tr><td>Señales reflejantes de seguridad</td><td>A bordo</td><td></td><td></td></tr><tr><td>Calzas</td><td>A bordo</td><td></td><td></td></tr><tr><td>RECIPIENTE, VÁLVULAS, ACCESORIOS (SEMIRREMOLQUE)</td><td></td><td></td></tr><tr><td>Recipiente</td><td>Libre de abolladuras, protuberancias, incisiones o cavidades</td><td></td><td></td></tr><tr><td>Conexiones del recipiente</td><td>Sin fuga</td><td></td><td></td></tr><tr><td>Coples</td><td>Sin fuga</td><td></td><td></td></tr><tr><td>Válvulas y accesorios</td><td>Sin fuga</td><td></td><td></td></tr><tr><td>Indicador de presión</td><td>Sin fuga y funcionando</td><td></td><td></td></tr><tr><td>Indicador de temperatura</td><td>Sin fuga y funcionando</td><td></td><td></td></tr><tr><td>Indicador de nivel</td><td>Sin fuga, funcionando y el nivel de llenado del Recipiente no excede el 90%</td><td></td><td></td></tr><tr><td>Manguera, en caso de contar con ella</td><td>Sin protuberancias</td><td></td><td></td></tr><tr><td>Sin cortes o raspaduras</td><td></td><td></td></tr><tr><td>Recubrimiento de hule</td><td></td><td></td></tr><tr><td>Sin daño o deformación en malla interna</td><td></td><td></td></tr><tr><td>Tornillería completa</td><td></td><td></td></tr><tr><td>Sin desgaste o daño al recubrimiento o accesorios</td><td></td><td></td></tr><tr><td>Válvula de recepción</td><td>Sin daños y sin fugas</td><td></td><td></td></tr><tr><td>SEMIRREMOLQUE</td><td></td><td></td></tr><tr><td>Perno Rey</td><td>Sin daños (deformaciones, en posición recta, sin desgaste)</td><td></td><td></td></tr><tr><td>Freno</td><td>Funciona</td><td></td><td></td></tr><tr><td>Conexiones y líneas eléctricas y de aire (del tractocamión a Semirremolque)</td><td>Sin daños</td><td></td><td></td></tr><tr><td>Patines</td><td>Funcionan</td><td></td><td></td></tr><tr><td>Sin daños</td><td></td><td></td></tr><tr><td>Luces</td><td>Completas y funcionando</td><td></td><td></td></tr><tr><td>Cintas reflejantes</td><td>Completas y visibles</td><td></td><td></td></tr><tr><td>Llantas</td><td>Dibujo homogéneo y sin daños</td><td></td><td></td></tr><tr><td>Presión conforme a la recomendación de fabricante</td><td></td><td></td></tr><tr><td>Rines</td><td>Sin daños</td><td></td><td></td></tr><tr><td>Birlos</td><td>Completos y sin daños</td><td></td><td></td></tr><tr><td>Guardafangos (Loderas).</td><td>Completos, sin daños</td><td></td><td></td></tr></tbody></table>","tipo_articulo":"anexo","titulo_nombre":"Apéndice A (Normativo)","capitulo_nombre":"Apéndice A (Normativo)","seccion_nombre":"A.2"},{"id":"4b870b65-c2a2-511f-ac27-21919af6885f","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":141,"identificador":"Numeral 12. Bibliografía","contenido":"<div>12. Bibliografía</div>\n<div>· Ley del Sector Hidrocarburos. Publicada en el Diario Oficial de la Federación el 18 de marzo de 2025.</div>\n<div>· Reglamento de la Ley del Sector Hidrocarburos. Publicado en el Diario Oficial de la Federación el 03 de octubre de 2025.</div>\n<div>· Reglamento del Servicio de Medicina Preventiva en el Transporte. Publicado en el Diario Oficial de la Federación el 01 de abril de 2004 y sus modificaciones.</div>\n<div>· Reglamento para el Transporte Terrestre de Materiales y Residuos Peligrosos. Publicado en el Diario Oficial de la Federación el 07 de abril de 1993. Última reforma publicada Diario Oficial de la Federación 20 de noviembre de 2012.</div>\n<div>· NORMA Oficial Mexicana NOM-007-SESH-2010, Vehículos para el transporte y distribución de Gas L.P.- Condiciones de seguridad, operación y mantenimiento. Publicada en el Diario Oficial de la Federación el 11 de julio de 2011.</div>\n<div>· NORMA Oficial Mexicana NOM-008-SE-2021, Sistema general de unidades de medida. Publicada en el Diario Oficial de la Federación el 29 de diciembre de 2023, y su aclaración publicada en el Diario Oficial de la Federación el 23 de abril de 2024.</div>\n<div>· NORMA Oficial Mexicana NOM-004-SCT/2008, Sistemas de identificación de unidades destinadas al transporte de substancias, materiales y residuos peligroso. Publicada en el Diario Oficial de la Federación el 18 de agosto de 2008.</div>\n<div>· NORMA Oficial Mexicana NOM-005-SCT/2008 Información de emergencia para el transporte de substancias, materiales y residuos peligrosos. Publicada en el Diario Oficial de la Federación el 14 de agosto de 2008</div>\n<div>· NORMA Oficial Mexicana NOM-006-SCT-2-2023, Aspectos básicos para la revisión ocular de la unidad destinada al transporte de mercancías peligrosas. Publicada en el Diario Oficial de la Federación el 23 de mayo 2024.</div>\n<div>· NORMA Oficial Mexicana NOM-012-SCT-2-2017, Sobre el peso y dimensiones máximas con los que pueden circular los vehículos de autotransporte que transitan en las vías generales de comunicación de jurisdicción federal. Publicada en el Diario Oficial de la Federación el 26 de diciembre de 2017.</div>\n<div>· NORMA Oficial Mexicana NOM-019-SCT2/2015, Especificaciones técnicas y disposiciones generales para la limpieza y control de remanentes de substancias y residuos peligrosos en las unidades que transportan materiales y residuos peligrosos. Publicada en el Diario Oficial de la Federación el 27 de enero de 2016.</div>\n<div>· NORMA Oficial Mexicana NOM-068-SCT-2-2014, Transporte terrestre-Servicio de autotransporte federal de pasaje, turismo, carga, sus servicios auxiliares y transporte privado-Condiciones físico-mecánica y de seguridad para la operación en vías generales de comunicación de jurisdicción federal. Publicada en el Diario Oficial de la Federación el 19 de enero de 2015.</div>\n<div>· NORMA Oficial Mexicana NOM-057-SCT2/2003, Requerimientos generales para el diseño y construcción de Auto-tanques destinados al transporte de gases comprimidos, especificación SCT 331. Publicada en el Diario Oficial de la Federación el 26 de enero de 2004.</div>\n<div>· NORMA Oficial Mexicana NOM-002-STPS-2010, Condiciones de seguridad-Prevención y protección contra incendios en los centros de trabajo. Publicada en el Diario Oficial de la Federación el 9 de diciembre de 2010.</div>\n<div>· NORMA Oficial Mexicana NOM-030-STPS-2009, Servicios preventivos de seguridad y salud en el trabajo-Funciones y actividades. Publicada en el Diario Oficial de la Federación el 22 de diciembre de 2009.</div>\n<div>· DECLARATORIA de vigencia de la Norma Mexicana NMX-Z-013-SCFI-2015, Guía para la estructuración y redacción de Normas (Cancela a la NMX-Z-013/1- 1977). Publicada en el Diario Oficial de la Federación el 18 de noviembre de 2015.</div>\n<div>· ACUERDO de la Comisión Reguladora de Energía que expide las Disposiciones administrativas de carácter general en materia de transporte y distribución por medios distintos a ductos, expendio mediante estación de servicio para autoconsumo y expendio al público de gas licuado de petróleo. Publicado en el Diario Oficial de la Federación el 13 de diciembre de 2018.</div>\n<div>· ACUERDO por el que se dan a conocer los criterios administrativos, requisitos y formatos para realizar los trámites y solicitar los servicios en materia de capacitación, adiestramiento y productividad de los trabajadores. Publicado en el Diario Oficial de la Federación el 14 de junio de 2013, y sus modificaciones.</div>\n<div>· Fire Safety Analysis Manual for LP-Gas Storage Facilities 2015, Developed by the National Fire Protection Association and the National Propane Gas Association (Manual de Análisis de Seguridad Contra Incendios para Instalaciones de Almacenamiento de Gas L.P. - Desarrollado por la Asociación Nacional de Protección Contra Incendios y la Asociación Nacional de Gas Propano)</div>\n<div>· NFPA 58:2016, Liquefied Petroleum Gas Code. (Código de Gas Licuado de Petróleo)</div>\n<div>· Code of Federal Regulations Title 49, Subtitle B, Chapter I, Pipeline and Hazardous Materials Safety Administration, Department of Transportation.</div>\n<div>· Code of Federal Regulations Title 49, Subtitle B, Chapter III, Federal Motor Carrier Safety Administration, Department of Transportation.</div>\n<div>· Código ASME Sección VIII Div. 1. Reglas para la Construcción de Recipientes a Presión</div>\n<div>· API 598 2016, Valve Inspection and Testing (Inspección y Pruebas en Válvulas).</div>\n<div>· API 510 2014, Pressure Vessel Inspection Code (Código de Inspección de Recipientes a Presión).</div>\n<div>· DIRECTIVA DIRDGGLP0012011, para la prestación de servicios de Distribución a Usuarios Finales y de Supresión de Fugas de Gas L.P.</div>\n<div>· Guide to Good Industry Practices for LPG Cylinders in the Distribution Channel, 2019, WLPGA</div>\n<div>· CERTIFIED EMPLOYEE TRAINING PROGRAM 2.2 Bobtail Delivery Operations (2019) Propane Education &amp; Research Council (PERC)</div>\n<div>· Guía de Recomendaciones para la Promoción de la Salud y Prevención de Adicciones en los Centros de Trabajo.</div>\n<div>· Programa Integral de Capacitación para la obtención de la licencia federal Tipo E de Autotransporte Federal y Transporte Privado de Materiales y Residuos Peligrosos.</div>\n<div>· DECRETO por el que se expide el Reglamento de la Ley del Sector Hidrocarburos. Publicado en el Diario Oficial de la Federación el 03 de octubre de 2025.</div>","tipo_articulo":"ordinario","titulo_nombre":"Bibliografía","capitulo_nombre":null,"seccion_nombre":null},{"id":"504d0171-678d-5a1a-b56b-2e2e0509820a","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":142,"identificador":"Transitorio Primero","contenido":"<div>PRIMERO. La presente Norma Oficial Mexicana de Emergencia NOM-EM-008-ASEA-2026, Transporte de Gas Licuado de Petróleo por medio de Auto-tanque y Semirremolque tendrá una vigencia de seis meses y entra en vigor a partir del 6 de octubre del 2026.</div>","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null},{"id":"7e4d1306-c0aa-5ab4-a5b9-c01113404d54","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":143,"identificador":"Transitorio Segundo","contenido":"<div>SEGUNDO. Los dictámenes de cumplimiento con la Norma Oficial Mexicana de Emergencia NOM-EM-006-ASEA-2025, que hayan sido emitidos con anterioridad a la fecha de entrada en vigor de la presente Norma Oficial Mexicana de Emergencia, serán reconocidos por la Agencia hasta el término de su vigencia.</div>","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null},{"id":"ce474e4a-f7c3-50d4-9844-4260a0ef31b2","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":144,"identificador":"Transitorio Tercero","contenido":"<div>TERCERO. Durante la vigencia de la presente Norma Oficial Mexicana de Emergencia, el Regulado debe cumplir los requisitos de capacitación establecidos en los numerales 7.1.2 y 7.1.6 inciso c), para operadores de Tractocamión-Semirremolque; o formar parte del programa anual de capacitación teórico-práctico referido en el numeral 7.1.1, de la presente Norma Oficial Mexicana de Emergencia incluyendo para este fin el tema de capacitación adicional referente a &quot;Revisión de la quinta rueda y maniobras de enganche y desenganche&quot;, y cumplir con los numerales 7.1.4, 7.1.5 y 7.1.6 inciso b); por lo que, en este último caso, no serán sujetos de Evaluación de la Conformidad los numerales 7.1.2, 7.1.3 y 7.1.6 inciso c).</div>","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null},{"id":"7d343828-2535-594d-87b4-5b2a8d97a1fe","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":145,"identificador":"Transitorio Cuarto","contenido":"<div>CUARTO. Los Regulados con Auto-tanques y Semirremolques con su respectivo Tractocamión de Transporte de Gas Licuado de Petróleo que se encuentren operando a la fecha de entrada en vigor de la presente Norma Oficial Mexicana de Emergencia y no cuenten con un dictamen vigente de operación y mantenimiento, contarán con 90 días naturales para obtenerlo.</div>","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null},{"id":"be09e493-d9cc-5b67-99ae-7ec8aae58a6d","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":146,"identificador":"Transitorio Quinto","contenido":"<div>QUINTO. Los Regulados que cuenten con Auto-tanques y Semirremolques de Transporte de GLP operando a la fecha de entrada en vigor de la presente Norma Oficial Mexicana de Emergencia, cuya antigüedad del Recipiente No Desmontable sea igual o mayor de 50 años a partir de su fecha de fabricación, contarán con la vigencia de esta Norma Oficial Mexicana de Emergencia para realizar la prueba hidrostática, prevista en la Tabla 2 del numeral 7.4.4, y en el numeral 7.4.5.4.</div>\n<div>Durante la vigencia de esta Norma Oficial Mexicana de Emergencia no será exigible la prueba hidrostática en Auto-tanques y Semirremolques en operación cuya antigüedad del Recipiente No Desmontable sea menor de 50 años a partir de su fecha de fabricación, para obtener el Dictamen de operación y mantenimiento.</div>","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null},{"id":"f54325b0-5eaf-593e-bf0e-8091bbf777d0","ley_id":"864ee23b-19ea-5c44-9b01-bd77e0320b11","orden":147,"identificador":"Transitorio Sexto","contenido":"<div>SEXTO. Las unidades de inspección acreditadas y aprobadas para evaluar la conformidad de la NOM-007-SESH-2010, Vehículos para el Transporte y distribución de Gas L.P.- Condiciones de seguridad, operación y mantenimiento, cuya aprobación se encuentre vigente podrán llevar a cabo el procedimiento de evaluación de la conformidad de esta Norma Oficial Mexicana de Emergencia durante la vigencia de esta.</div>\n<div>______________________________</div>","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"Información editorial","orden":0},{"nivel":"capitulo","nombre":"Preámbulo","orden":1},{"nivel":"capitulo","nombre":"Objetivo","orden":2},{"nivel":"capitulo","nombre":"Campo de aplicación","orden":3},{"nivel":"capitulo","nombre":"Objetivos legítimos de interés público","orden":4},{"nivel":"capitulo","nombre":"Referencias normativas","orden":5},{"nivel":"capitulo","nombre":"Términos, definiciones, términos abreviados, símbolos y siglas","orden":6},{"nivel":"capitulo","nombre":"Inicio de operación","orden":7},{"nivel":"capitulo","nombre":"Operación y mantenimiento","orden":8},{"nivel":"capitulo","nombre":"Término de operación","orden":9},{"nivel":"capitulo","nombre":"Procedimiento de Evaluación de la Conformidad","orden":10},{"nivel":"capitulo","nombre":"Grado de concordancia con normas internacionales","orden":11},{"nivel":"capitulo","nombre":"Verificación de la Norma Oficial Mexicana de Emergencia","orden":12},{"nivel":"capitulo","nombre":"Bibliografía","orden":13},{"nivel":"capitulo","nombre":"Apéndice A","orden":14},{"nivel":"capitulo","nombre":"Transitorios","orden":15},{"nivel":"seccion","nombre":"Seguridad industrial y operativa","orden":16},{"nivel":"seccion","nombre":"Transporte de gas licuado de petróleo","orden":17},{"nivel":"seccion","nombre":"Auto-tanques y semirremolques","orden":18},{"nivel":"seccion","nombre":"Integridad mecánica y mantenimiento","orden":19},{"nivel":"seccion","nombre":"Capacitación de operadores","orden":20},{"nivel":"seccion","nombre":"Evaluación de la conformidad","orden":21},{"nivel":"seccion","nombre":"Protección ambiental y manejo de residuos","orden":22},{"nivel":"seccion","nombre":"Revisión visual diaria","orden":23}]}$payload$::jsonb; lid uuid;
BEGIN
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 lid := (p->'ley'->>'id')::uuid;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*) FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'') IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*) FROM public.articulos a WHERE a.ley_id=l.id) fragmentos,(SELECT count(*) FROM public.temas t WHERE t.ley_id=l.id) temas FROM public.leyes l WHERE l.id='864ee23b-19ea-5c44-9b01-bd77e0320b11';
